  const [floralRatio, setFloralRatio] = useState(70);
  const [floralOverrides, setFloralOverrides] = useState({ note: "", rows: [] });

  // ═══ ZONE PHOTO FILTERS (Build canvas) — seeded from a reference video's own taxonomy when
