  const [zpFilters, setZpFilters] = useState({ eventType: [], venueType: [], designStyle: [], colorPalette: [], timeSetting: [], venue: [], tier: [] });
  const zpToggleFilter = useCallback((cat, val) => {
    // `prev[cat] || []` is a deliberate backstop, not defensive noise. Several places REPLACE this
    // whole object (clear-all in two spots on Build, and the video-tag seed), so any category whose
    // key one of them forgets to list would arrive here undefined and throw on .includes — a filter
    // pill that crashes the build page. Every such site does list every key today; this makes
    // forgetting one a no-op instead of a crash.
    setZpFilters(prev => {
      const cur = prev[cat] || [];
      return { ...prev, [cat]: cur.includes(val) ? cur.filter(v => v !== val) : [...cur, val] };
    });
  }, []);
  const zpHasFilters = Object.values(zpFilters).some(a => a.length > 0);
  // Which categories HIDE a photo. All seven filter chips hide now — venue type, design style,
  // time/setting and tier used to only "rank" a non-match lower instead of hiding it (the thinking
  // being too little is tagged along those dimensions for an exact match to leave enough photos to
  // build a zone from), but the grid view never even applied that ranking — a selected filter had
  // ZERO visible effect there, which read as the filter panel being broken rather than lenient
  // (confirmed: an Indoor-tagged photo kept showing with "Outdoor" selected, with no indication why).
  // The empty-state fallback (BUG-7, "No X photos match your filters" + Clear) already exists for
  // when a hard filter leaves too few results, so there's a graceful way out if tagging is sparse —
  // the safety net this used to be demoted to avoid is already there.
  const zpFilterPhoto = useCallback((li) => {
    if (!li) return true;
    const tags = li.tags || {};
    const evVals = zpFilters.eventType || [];
    if (evVals.length) {
      const it = tags.eventType || [];
      if (!evVals.some(v => it.includes(v))) return false;
    }
    const palVals = zpFilters.colorPalette || [];
    if (palVals.length && !palVals.some(v => paletteInList(tags.colorPalette || [], v))) return false;
    const vtVals = zpFilters.venueType || [];
    if (vtVals.length && !vtVals.some(v => (tags.venueType || []).includes(v))) return false;
    const dsVals = zpFilters.designStyle || [];
    if (dsVals.length && !dsVals.some(v => (tags.designStyle || []).includes(v))) return false;
    const tsVals = zpFilters.timeSetting || [];
    if (tsVals.length && !tsVals.some(v => (tags.timeSetting || []).includes(v))) return false;
    const tierVals = zpFilters.tier || [];
    if (tierVals.length && !tierVals.some(v => (tags.tier || []).includes(v))) return false;
    const venueVals = zpFilters.venue || [];
    if (venueVals.length) {
      let url = ""; try { url = decodeURIComponent(String(li.url || "")); } catch { url = String(li.url || ""); }
      const hay = (String(tags.venue || "") + " " + url).toLowerCase();
      if (!venueVals.some(v => hay.includes(String(v).toLowerCase()))) return false;
    }
    return true;
  }, [zpFilters]);
  // Palette is now enforced above (zpFilterPhoto) — every photo reaching the sort step already
  // matches it, or no palette was picked. Kept as its own function only for that "no preference"
  // check to stay in one place; not used for ranking anymore (nothing left to rank by).
  const zpPaletteMatch = useCallback((li) => {
    const vals = zpFilters.colorPalette || [];
    if (!vals.length) return true;
    if (!li) return true;
    return vals.some(v => paletteInList(li.tags?.colorPalette || [], v));
  }, [zpFilters]);
  // Venue is a preference, not a filter: too few photos are tagged per venue for an exact match to
  // leave enough to build from, so the zone strips rank the chosen venue first and keep the rest
  // rather than hiding them. Matches the photo's venue TAG or its folder path — photos are often
  // filed under "inhouse venues/<venue>/…" — so picking "Emerald Green" also catches ones that only
  // carry it in the path. True when nothing is picked, i.e. no preference to express.
  const zpVenueMatch = useCallback((li) => {
    const venueVals = zpFilters.venue || [];
    if (!venueVals.length) return true;
    if (!li) return true;
    let url = ""; try { url = decodeURIComponent(String(li.url || "")); } catch { url = String(li.url || ""); }
    const hay = (String(li.tags?.venue || "") + " " + url).toLowerCase();
    return venueVals.some(v => hay.includes(String(v).toLowerCase()));
  }, [zpFilters]);
  // venueType / designStyle / timeSetting — demoted from the old hard-filter loop to the same kind
  // of rank-not-hide preference as venue/palette used to be, for the same reason: too few photos
  // carry an exact match along these to leave enough to build a zone from.
  const zpVenueTypeMatch = useCallback((li) => {
    const vals = zpFilters.venueType || [];
    if (!vals.length) return true;
    if (!li) return true;
    return vals.some(v => (li.tags?.venueType || []).includes(v));
  }, [zpFilters]);
  const zpDesignStyleMatch = useCallback((li) => {
    const vals = zpFilters.designStyle || [];
    if (!vals.length) return true;
    if (!li) return true;
    return vals.some(v => (li.tags?.designStyle || []).includes(v));
  }, [zpFilters]);
  const zpTimeSettingMatch = useCallback((li) => {
    const vals = zpFilters.timeSetting || [];
    if (!vals.length) return true;
    if (!li) return true;
    return vals.some(v => (li.tags?.timeSetting || []).includes(v));
  }, [zpFilters]);
  // Tier (Gold / Silver / Platinum) — a preference, NOT a hard filter, for the reason stated above,
  // and measured rather than assumed: only about half the library carries a tier tag at all. Hiding
  // on it would drop every untagged photo the moment a tier was picked, which is most of what there
  // is to build from. So it ranks: pick Gold and the Gold-tagged photos come first, the rest stay.
  const zpTierMatch = useCallback((li) => {
    const vals = zpFilters.tier || [];
    if (!vals.length) return true;
    if (!li) return true;
    return vals.some(v => (li.tags?.tier || []).includes(v));
  }, [zpFilters]);

  // ═══ ZONE UPLOAD STATE — VERBATIM (Cloudinary + AI tag) ═══
  const [zoneUploading, setZoneUploading] = useState(null); // elKey currently uploading
  const [zoneUploadReview, setZoneUploadReview] = useState(null);
  // Library ids uploaded into each zone this session, newest first — { [zoneKey]: libId[] }. Build's
  // grid shows them right after favourites (and pulls them in even before the zone's cached photo
  // pool refetches), so a fresh upload never looks like it vanished.
  const [recentUploads, setRecentUploads] = useState({});
  const [zurElSearch, setZurElSearch] = useState("");
  const [inspQ, setInspQ] = useState("");
  const [inspResults, setInspResults] = useState([]);
  const [inspLoading, setInspLoading] = useState(false);
  const [aiPrompt, setAiPrompt] = useState("");
  const [aiResult, setAiResult] = useState(null);
  const [aiLoading, setAiLoading] = useState(false);
  const [pptLoading, setPptLoading] = useState(false);
  const [pptDone, setPptDone] = useState(false);
  const [savedInsps, setSavedInsps] = useState([]);
  const [copied, setCopied] = useState(false);
  const [sourceEvent, setSourceEvent] = useState(null);
  const [sourceVideo, setSourceVideo] = useState(null);
  const [filterPriority, setFilterPriority] = useState(DEFAULT_FILTER_PRIORITY);
  // Persist photo-filter priority (single-source admin config) — was only setState'd, so it reset on
  // refresh. Stored in the settings row FILTER_PRIORITY_SK (config, single-writer — not clobber-prone).
  const saveFilterPriority = useCallback((np) => { setFilterPriority(np); reliableSave(FILTER_PRIORITY_SK, JSON.stringify(np), "Filter priority").catch(() => {}); }, []);
  // Sub-categories flagged in Pricing as NOT taggable — array of "cat::sub" keys. Hidden from the
  // element-search boxes (Build + Library tagger) and dropped from the AI tagger's vocabulary, so
  // already-costed structural subs (truss/platform/carpet/fabric) and IMS-only subs (tools) can't
  // be re-added during tagging. Items still exist in pricing & IMS inventory.
  const [tagHiddenSubs, setTagHiddenSubs] = useState([]);
  const [customTripRate, setCustomTripRate] = useState(0);
  const [venueCustom, setVenueCustom] = useState(false);
  const [customGensets, setCustomGensets] = useState(null);
  const [elInspo, setElInspo] = useState({});
  const [elInspoLoading, setElInspoLoading] = useState({});
  const [elSelectedPhoto, setElSelectedPhoto] = useState({});
  // Zone-grid tick selection ({ [zoneKey]: Set<libraryPhotoId> }) — the candidate photos ticked in
  // ▦ grid view before (or without ever) hitting "Pin". Lifted here (was local to StudioBuild.jsx)
  // so it rides the same per-function snapshot/restore path as elSelectedPhoto/zoneOrder/customZones
  // below — a salesperson's in-progress tick set now survives a session reload/function switch
  // instead of resetting every remount.
  const [grpSel, setGrpSel] = useState({});
  const [elNotes, setElNotes] = useState({});
  const [elCostOpen, setElCostOpen] = useState({});
  const [customZones, setCustomZones] = useState([]);
  // Which seed zone type the "+ Add Zone" picker is on. A zone key means the zone it adds is a second
  // Stage / Entry Passage / … and behaves exactly like the original — photo strip, elements, truss,
  // platform, pricing — via customZones[].sourceType. "" is just the unpicked placeholder.
  const [newCzSrc, setNewCzSrc] = useState("");
  const [elGallery, setElGallery] = useState(null);
  const [galleryIdx, setGalleryIdx] = useState(null);
  const [webPreview, setWebPreview] = useState(null);
  const [zoneConfig, setZoneConfig] = useState({});
  const [activeZones, setActiveZones] = useState([]);
  // ── PER-DEAL ZONE ORDER ──
  // An explicit list of zone keys in the order this deal wants them. Empty = "no opinion", and
  // everything falls back to the admin's configured Zone Types order exactly as before.
  //
  // Per FUNCTION, not per deal: zoneConfig, enabledEls and customZones are all per function, so a
  // single shared order could name zones a given function does not have. It rides in the same
  // fnBuilds snapshot as those, which is what scopes it to this client's session and no one
  // else's — nothing here is written to the shared Zone Types settings.
  const [zoneOrder, setZoneOrder] = useState([]);
  const [rcItems, setRcItems] = useState(RC_D);
  const [rcCats, setRcCats] = useState(RC_CATS_DEFAULT);
  const [rcSubcatFactors, setRcSubcatFactors] = useState([]); // IMS-owned; read-only here until Phase 2
  // IMS inventory, always-on (not deal-scoped like dealCheckData.inventory) — needed by Library's
  // "+Add element" search, which sources directly from inventory now, not the Rate Card.
  const [imsInventory, setImsInventory] = useState([]);
  // Blocks for just the active function's date — warms once loadAvailability/activeFnMeta exist
  // below. Powers Build view's availability-aware pricing for invId-sourced elements only.
  const [activeBlocksForDate, setActiveBlocksForDate] = useState({});
  // Per-event breakdown of the SAME date's blocks ({ itemId: [{eventId, qty}, …] }) — fetchIMSData
  // already computes this (blocksDetailForDate), it just used to get thrown away the moment this
  // effect destructured only blocksForDate out of loadAvailability's result. getElPriceFromInventory
  // needs it to net THIS deal's own reservation out live, instead of off the dcReservedInventory
  // cache (see netOwnReservedBlocksLive's own comment for why that cache alone isn't reliable).
  const [activeBlocksDetailForDate, setActiveBlocksDetailForDate] = useState({});
  // Same thing, but for EVERY function's own date, not just whichever one is the open Build tab —
  // { [date]: blocksForDate }. eventGrandTotal/calcFunctionBreakdown need each function's shortfall
  // priced against ITS OWN date, not the active function's; without this, checking availability at
  // all was restricted to the active function only (activeBlocksForDate has no other date to check
  // against), which meant the shortfall discount silently moved to whichever function you had open —
  // the combined total shifted every time you switched tabs, nothing about the event having changed.
  const [blocksByDate, setBlocksByDate] = useState({});
  // each date's per-event holds, so a function's own reservation is netted against ITS date (not the open function's)
  const [blocksDetailByDate, setBlocksDetailByDate] = useState({});
  const [libElSearch, setLibElSearch] = useState("");
  const [trVenues, setTrVenues] = useState(TR_DV);
  const [truckCap, setTruckCap] = useState(TR_DTC);
  // Flips true once the RC_SK_TR settings row has actually been fetched (found data or confirmed
  // there's none) — trVenues/truckCap start out holding TR_DV/TR_DTC seed defaults until then, and
  // a write gated on trVenues alone (below, the genset migration) would fire on THAT seed state
  // during the async fetch's window and persist the seed truckCap over whatever was really saved.
  const trSettingsLoadedRef = useRef(false);
  // ── ARE THE PRICING INPUTS IN YET? ──
  // Every input the estimate is built from starts at a hardcoded SEED default, not at "unknown":
  // rcItems = RC_D (57 real items with real rates), trVenues = TR_DV, truckCap = TR_DTC,
  // bufferTiers = TR_DBT, gensetRate = 28000, and the truss/masking/carpet/print/platform rate
  // tables start []. So the first render computes a complete, entirely plausible total out of stale
  // defaults, and then each dataset landing in its own await/setState tick moves it again — the
  // rate card, the scaling factors, inventory, transport, then the five structure-rate tables.
  // That is the four-or-five different prices on a refresh: not a render glitch, a real calculation
  // over an incomplete dataset, several times over.
  // This flag marks the point where all of them have arrived. It gates the estimate tile (skeleton
  // until then) and the price-derived fields (tier/total/decorTotal/transportTotal/fnTotals) that
  // saveSession writes — NOT the save itself (see autoSaveBuild's own comment): a real edit must
  // never wait on this, only the numbers that would otherwise be a wrong sum over seed-default
  // rates. No ref counterpart needed — saveSession reads this via its own closure (it's in its
  // dependency array), not off a ref like the switchingRef/fnSwitchingRef guards autoSaveBuild uses.
  // The same seed-defaults-look-real trap already cost this codebase real data once; see the guard
  // comment on the genset migration effect below.
  const [pricingReady, setPricingReady] = useState(false);
  // Backstop. The flag is set inline once the last rate table lands; every step of that boot
  // sequence is individually try/caught, but a throw between an await and the flag would leave the
  // tile on a skeleton forever. Ten seconds is far past a normal boot, so this only ever fires when
  // something has genuinely gone wrong — and a possibly-settling price beats a permanent spinner.
  useEffect(() => {
    if (pricingReady) return;
    const t = setTimeout(() => setPricingReady(true), 10000);
    return () => clearTimeout(t);
  }, [pricingReady]);
  const [floralPerTruck, setFloralPerTruck] = useState(50000);
  // Two genset sizes are hired, and an event can need BOTH — a big unit plus a smaller one — so
  // each size carries its own count. 125 KVA keeps the original `gensetRate` key and the existing
  // customGensets override; 62 KVA mirrors it with its own override — null means "follow the
  // venue's own 62 KVA count" (resolveVenueGensets), an explicit number (0 included) pins it.
  const [gensetRate, setGensetRate] = useState(28000);      // 125 KVA — billed to the client
  const [gensetRate62, setGensetRate62] = useState(18000);  // 62 KVA — billed to the client
  // Our own cost per genset (what the vendor actually charges us), separate from the client-billed
  // rate above — Deal Check's own Power tab and IMS need OUR figure to track real margin; Build/
  // Summary keep showing gensetRate/gensetRate62 to the guest, completely unchanged. Defaults to 0
  // (not yet set) rather than mirroring the client rate, so an untouched value reads honestly as
  // "cost not entered yet" instead of silently claiming 0% margin on every genset.
  const [gensetCostRate, setGensetCostRate] = useState(0);      // 125 KVA — our cost
  const [gensetCostRate62, setGensetCostRate62] = useState(0);  // 62 KVA — our cost
  const [genset62, setGenset62] = useState(null);           // override for the smaller unit, per deal — null = follow venue
  const [bufferTiers, setBufferTiers] = useState(TR_DBT);
  const [newTC, setNewTC] = useState({ item: "", perTruck: 0, unit: "pc" });

  // ═══ TEMPLATE STATE ═══
  const [templates, setTemplates] = useState(TPL_DEFAULTS);
  const [tplEdit, setTplEdit] = useState(null);
  const [tplTab, setTplTab] = useState("list");

  // ═══ ZONE PHOTO GROUPS ═══ { [areaName]: { [functionType]: [libraryPhotoId, …] } }
  // Hand-picked in Manage → Library → Grouping; Build floats the group for the active function to
  // the front of that zone's strip. See lib/studio/zoneGroups.js for the shape and the lookup rules.
  const [zoneGroups, setZoneGroups] = useState({});
  // Mirror of the above. writeZoneGroup needs the pre-save value to roll back to, and reading it
  // from a ref keeps the callback free of a zoneGroups dependency — otherwise every group edit
  // would mint a new writeZoneGroup, and with it a new getLibPhotosForZone.
  const zoneGroupsRef = useRef({});

  // ═══ ZONE DEFINITIONS STATE ═══
  const [zoneDefs, setZoneDefs] = useState({ elements: {}, meta: JSON.parse(JSON.stringify(ZONE_META)) });
  const zoneMeta = useMemo(() => zoneDefs.meta || ZONE_META, [zoneDefs]);
  const zoneKeys = useMemo(() => Object.keys(zoneMeta), [zoneMeta]);
  const zoneLabelsD = useMemo(() => {
    const labels = {};
    Object.entries(zoneMeta).forEach(([k, v]) => {
      labels[k] = { label: v.label || k, icon: v.icon || ZONE_LABELS[k]?.icon || "📦" };
    });
    return labels;
  }, [zoneMeta]);
  const [zdEditZone, setZdEditZone] = useState("stage");

  // ═══ Active function meta (derived from activeFnIdx) ═══
  const activeFnMeta = useMemo(() => {
    if (activeFnIdx === 0) {
      return { type: fn || "", date: clientDate || "", venue: venue || "", shift: clientShift || "", pax: clientPax || "" };
    }
    const ef = extraFunctions[activeFnIdx - 1];
    if (!ef) {
      return { type: fn || "", date: clientDate || "", venue: venue || "", shift: clientShift || "", pax: clientPax || "" };
    }
    return { type: ef.type || "", date: ef.date || "", venue: ef.venue || "", shift: ef.shift || "", pax: ef.pax || "" };
  }, [activeFnIdx, fn, clientDate, venue, clientShift, clientPax, extraFunctions]);

  useEffect(() => {
    const maxIdx = extraFunctions.length;
    if (activeFnIdx > maxIdx) setActiveFnIdx(Math.max(0, maxIdx));
  }, [extraFunctions.length, activeFnIdx]);

  // ═══ Snapshot / restore Build state for per-function canvases — VERBATIM ═══
  const snapshotBuildState = () => ({
    enabledEls, elTiers, zoneConfig, zoneElements, itemQty, itemGrades,
    customMode, activeZones, zoneOrder, customZones,
    elSelectedPhoto, elInspo, elNotes, elCostOpen,
    // Sets aren't JSON-safe — flatten to plain arrays here, the same serialization-boundary approach
    // elSelectedPhoto's own sibling fields use, and rebuild the Sets in restoreBuildState below.
    grpSel: Object.fromEntries(Object.entries(grpSel).map(([k, set]) => [k, [...set]])),
    sourceVideo, sourceEvent,
    savedInsps, selectedMoods, selectedPalettes, floralRatio,
    customGensets, genset62, customTripRate,
    floralOverrides,
  });
  // Lives in lib/studio/sessionData now, so the SAVE path and Browse's banner cannot drift apart on
  // what counts as "has data" — they disagreeing is what let an empty auto-save erase a visible card.
  const fnSnapHasData = (snap) => {
    return fnSnapHasDataPure(snap);
  };
  const restoreBuildState = (s) => {
    if (!s) {
      setEnabledEls({}); setElTiers({}); setZoneConfig({}); setZoneElements({});
      setItemQty({}); setItemGrades({}); setCustomMode({}); setActiveZones([]);
      // zoneOrder resets with the rest. It is per function, so switching to one that has no saved
      // build must not inherit the previous function's arrangement.
      setZoneOrder([]);
      setCustomZones([]); setElSelectedPhoto({}); setGrpSel({}); setElInspo({}); setElNotes({});
      setElCostOpen({}); setSourceVideo(null); setSourceEvent(null);
      setSavedInsps([]); setSelectedMoods([]); setSelectedPalettes([]); setFloralRatio(70);
      setCustomGensets(null); setGenset62(null); setCustomTripRate(0);
      setFloralOverrides({ note: "", rows: [] });
      return;
    }
    setEnabledEls(s.enabledEls || {});
    setElTiers(s.elTiers || {});
    setZoneConfig(s.zoneConfig || {});
    setZoneElements(s.zoneElements || {});
    setItemQty(s.itemQty || {});
    setItemGrades(s.itemGrades || {});
    setCustomMode(s.customMode || {});
    setActiveZones(s.activeZones || []);
    setZoneOrder(s.zoneOrder || []);
    setCustomZones(s.customZones || []);
    setElSelectedPhoto(s.elSelectedPhoto || {});
    setGrpSel(Object.fromEntries(Object.entries(s.grpSel || {}).map(([k, arr]) => [k, new Set(arr)])));
    setElInspo(s.elInspo || {});
    setElNotes(s.elNotes || {});
    setElCostOpen(s.elCostOpen || {});
    setSourceVideo(s.sourceVideo || null);
    setSourceEvent(s.sourceEvent || null);
    setSavedInsps(s.savedInsps || []);
    setSelectedMoods(s.selectedMoods || []);
    setSelectedPalettes(s.selectedPalettes || []);
    setFloralRatio(typeof s.floralRatio === "number" ? s.floralRatio : 70);
    setCustomGensets(typeof s.customGensets === "number" ? s.customGensets : null);
    setGenset62(typeof s.genset62 === "number" ? s.genset62 : null);
    setCustomTripRate(typeof s.customTripRate === "number" ? s.customTripRate : 0);
    setFloralOverrides(
      s.floralOverrides && typeof s.floralOverrides === "object"
        ? { note: s.floralOverrides.note || "", rows: Array.isArray(s.floralOverrides.rows) ? s.floralOverrides.rows : [] }
        : { note: "", rows: [] }
    );
  };
  // ═══ FUNCTION SWITCH ═══
  // Everything here is read from refs rather than the render closure. A switch re-renders the whole
  // build, which is slow enough that a second click lands while React is still working — and that
  // click's handler comes from the last COMMITTED render, i.e. before the first switch. Reading
  // `activeFnIdx` and `fnBuilds` from that stale closure was losing client data two ways:
  //
  //   1. `fnBuilds[newIdx]` read a stale map, so switching back to a function whose build had only
  //      just been stored restored `null` instead — blanking it on screen, after which the 1.5s
  //      autosave wrote that blank over the client's saved session.
  //   2. The outgoing snapshot was filed under the stale index, so it could overwrite a DIFFERENT
  //      function's build with this one's.
  //
  // Refs are updated at commit, so curIdx/builds/snapshot always agree with each other, and the ref
  // is advanced synchronously below so a burst of clicks chains correctly instead of each one
  // starting from the same stale point.
  const activeFnIdxRef = useRef(0);
  // activeFnIdxRef (above) is written OPTIMISTICALLY, synchronously, the instant switchActiveFn is
  // called — before the transition it starts has actually rendered anything. committedFnIdxRef is
  // the other half of the same guarantee activeFnIdxRef/fnBuildsRef/snapshotFnRef already promise
  // each other ("refs are updated at commit, so curIdx/builds/snapshot always agree"): it is set in
  // the SAME useLayoutEffect as snapshotFnRef below, so it only ever reflects whichever function's
  // canvas is ACTUALLY on screen right now — never a switch that's merely been started.
  // Real, regression-confirmed gap this closes (owner report 2026-11-10, Rakesh Taneja): the 3-second
  // busy backstop a few lines down clears switchingRef even when a switch's transition never actually
  // committed (slow device, exactly the reported iPad) — activeFnIdxRef is by then already sitting on
  // the NEW (never-rendered) index, while the live canvas snapshotFnRef would capture still shows the
  // OLD function. A click landing in that reopened window used to read curIdx off activeFnIdxRef and
  // file a snapshot of the wrong (still-showing) function under the wrong (never-rendered) index —
  // the exact "one function's build silently became a byte-for-byte copy of another's" symptom.
  // committedFnIdxRef can't be fooled this way: it only ever advances when activeFnIdx itself commits.
  const committedFnIdxRef = useRef(0);
  const fnBuildsRef = useRef({});
  // Same reason as activeFnIdxRef/fnBuildsRef: saveSession stamps each function's OWN type/date/
  // venue from these four (fn/clientDate/venue = function 1's own fields, extraFunctions = every
  // other function's), and a timer-fired autosave can land in the same gap between a Event-Info
  // edit's setState and the re-render that refreshes saveSession's closure — filing function 1's
  // (or another function's) OLD type/date/venue onto a snapshot whose index/content were already
  // reading fresh from activeFnIdxRef/fnBuildsRef. Confirmed live (Sahiba & Vineet, 2026-11-04):
  // Haldi's (fn_idx 0) own studio_sessions row got stamped fn_label "Wedding"/event_date 2026-11-24
  // while its zoneElements kept evolving as ordinary, distinct Haldi edits — the metadata went stale
  // the exact way the content used to before activeFnIdxRef/fnBuildsRef existed.
  const fnMetaRef = useRef({ fn: "", clientDate: "", venue: "", extraFunctions: [], clientShift: "", clientPax: "", clientPalette: "Custom", clientFlowerPalette: "", clientBrideGroom: "" });
  const snapshotFnRef = useRef(null);
  const switchingRef = useRef(false);
  // Switching functions replaces zoneElements/zoneConfig/etc with the target function's own
  // snapshot — the exact same state the debounced-edit effect below watches for real edits, so a
  // pure tab switch looked identical to an edit and scheduled a save (plus, on a booked deal, a
  // full uncached inventory+blocks regenerate — see autoSaveBuild's opts.edited branch) every time.
  // Fast switching could then queue that heavy regenerate right as the next switch's transition was
  // trying to render, freezing the screen on whichever function was mid-switch. Set synchronously
  // here, before the transition commits the swapped state; the debounced-edit effect reads and
  // clears it the one time it fires for this switch, skipping the schedule for that pass only — a
  // genuine edit (which never sets this ref) schedules normally.
  const fnSwitchNoSaveRef = useRef(false);
  // Set whenever loadClientSession runs — i.e. a fresh visit/meeting has just been opened, whether
  // starting clean or resuming a past draft. The rolling auto-save below normally collapses
  // consecutive auto-drafts into the same array slot (so a 15s background timer doesn't spam the
  // history) — but that collapsing must not carry across a Load, or the new meeting's first autosave
  // overwrites the very session that was just resumed, silently erasing the prior meeting's build.
  // saveSession clears this on the first save after a load, so collapsing resumes as normal within
  // the new meeting.
  const sessionBoundaryRef = useRef(false);
  // What the top saved session (sessions[0]) was when THIS tab last loaded or saved this client —
  // the build-path sibling of Deal Check's dcSaveBaselineRef (~line 9153, same fix, same reasoning).
  // saveSession compares this against the live sessions[0] read fresh at save time
  // (prevSnapForTotals) to tell "someone else saved a newer build while I was editing" apart from
  // "my own last write echoing back", instead of blindly overwriting whichever tab's autosave lands
  // last — the exact bug already once caught and only half-fixed in this file (see the "DELETION
  // DISABLED" note near saveSession's own studio_sessions write).
  const buildSaveBaselineRef = useRef(null);
  const buildConflictWarnedAtRef = useRef(0);
  // Which `${fnIdx}:${fnIdx}:${sourceVideoId}` pairs duplicateSourceVideoFnIdxs has already warned
  // about this client — see the effect right after allFunctionData's own definition. Reset on every
  // loadClientSession (a new client/deal) so a previous client's dismissed pairs never suppress a
  // genuinely new collision on the next one, and a genuinely new deal starts with a clean slate.
  const warnedVideoPairsRef = useRef(new Set());
  // A plain function, `(newIdx) => oldIdx`, describing whatever removal(s) the deal's prices
  // haven't caught up to yet — null when there's nothing pending. See saveSession's own "ONE PRICE
  // PER FUNCTION" fnTotals comment for why this exists: that carry-forward reads prev[i] by raw
  // position, with no idea a removal shifted every later function down. Without this, the function
  // now sitting at position i inherits whatever price belonged to the REMOVED function at that old
  // position, instead of its own. Decor content is untouched either way — this is a
  // displayed-price-only bug.
  // Two different writers, unified on ONE shape (a function, not an array/object split) specifically
  // so they COMPOSE: a prior design kept removeFunction's "just one more index shifted" case as a
  // plain array and loadClientSession's "here's the exact mapping, rebuilt from identity" case as a
  // plain object, and a removal landing between a load and its first save had no way to combine the
  // two (regression-caught: it had to pick one and silently drop the other, a real gap). Composing
  // function closures has no such limit, however many times either side contributes before a save
  // finally persists:
  //   - removeFunction (StudioEventInfo.jsx, the same-tab case) only knows "this index just
  //     vanished" — wraps whatever resolver is already here (identity if none) with one more shift.
  //   - loadClientSession (the cross-reload case: client.functions already reflects a removal that
  //     never reached a PERSISTED session, because only sessions[0] is held back, not the client row
  //     — see saveSession's own "Only the SESSIONS are held back" comment) derives the exact mapping
  //     from its own identity-based build relocation and sets a fresh resolver directly, replacing
  //     whatever was here (a load always re-derives the full picture from scratch, so there's nothing
  //     to compose with at that point).
  // Consumed (cleared to null) the moment a save actually persists — see saveSession's own "consumed
  // HERE" comment — not merely the next save that runs, since a held-back autosave must not burn the
  // one use this gets before the save that actually needs it.
  const pendingFnTotalsRemapRef = useRef(null);
  const emptySaveWarnedRef = useRef(false); // the "deal shows empty but has a saved build" warning, said once until a build is back
  useEffect(() => { activeFnIdxRef.current = activeFnIdx; switchingRef.current = false; }, [activeFnIdx]);
  useEffect(() => { fnBuildsRef.current = fnBuilds; }, [fnBuilds]);
  // useLayoutEffect, not useEffect, and no deps array — runs on EVERY commit, matching saveSessionRef's
  // own stronger guarantee (a plain useEffect is a passive effect; React can run it in a later task
  // than the commit, leaving a window where a timer could fire between this commit and that effect —
  // confirmed real by the stricter regression pass on this fix: a Deal Check/client-switch edit inside
  // that window could file a NEWLY-active client's own metadata under the PREVIOUS client's state).
  useLayoutEffect(() => { fnMetaRef.current = { fn, clientDate, venue, extraFunctions, clientShift, clientPax, clientPalette, clientFlowerPalette, clientBrideGroom }; });
  // Layout for the same reason as saveSessionRef below — switchActiveFn calls this one
  // SYNCHRONOUSLY on the click and files the result as the function's build, so it should be
  // reading the latest commit rather than whatever was current before the last paint.
  // committedFnIdxRef (see its own comment, next to activeFnIdxRef) is set HERE, in the same
  // layout effect as snapshotFnRef, deliberately — they must only ever change together, since one
  // names which function a snapshot belongs to and the other takes the snapshot itself.
  useLayoutEffect(() => { snapshotFnRef.current = snapshotBuildState; committedFnIdxRef.current = activeFnIdx; });

  // Rebuilding a function's whole canvas is heavy enough to block for a moment. Marked as a
  // transition so React keeps the page interactive while it renders and tells us it's working
  // (`isFnSwitching`) — a plain flag set alongside the switch would commit in the same batch as
  // the finished render, so it could never be seen. `fnPending` is the one URGENT update: the pill
  // has to light up on click, otherwise the click reads as ignored and gets repeated.
  const [isPendingFnRender, startFnSwitch] = useTransition();
  const [fnPending, setFnPending] = useState(null);
  useEffect(() => { setFnPending(null); }, [activeFnIdx]);

  // ═══ THE BUSY WINDOW ═══ "You clicked, and what's on screen is not yet this function."
  //
  // Neither `isPending` nor comparing fnPending to activeFnIdx is reliable on its own: both depend
  // on React giving us a render BETWEEN the click and the switch committing, and when it schedules
  // the urgent update together with the transition there is no such render — the flag flips true
  // and false within one commit and the loading state never paints. That's why the stale card kept
  // showing through.
  //
  // So the busy flag is owned outright and held for a minimum, guaranteeing the loading state is
  // actually seen and that a stale card can never flash in its place. It stays up longer if the
  // switch itself takes longer.
  const FN_BUSY_MIN_MS = 200; // was 400: long enough to be seen, short enough not to read as the switch being slow
  const [fnBusy, setFnBusy] = useState(false);
  const fnBusyStartRef = useRef(0);
  // Runs once the new index has committed — i.e. the switch is done — then waits out whatever is
  // left of the minimum so the message doesn't blink.
  useEffect(() => {
    if (!fnBusyStartRef.current) return;
    const left = Math.max(0, FN_BUSY_MIN_MS - (performance.now() - fnBusyStartRef.current));
    const t = setTimeout(() => { fnBusyStartRef.current = 0; setFnBusy(false); }, left);
    return () => clearTimeout(t);
  }, [activeFnIdx]);
  // A BACKSTOP, NOT A SECOND TIMER. The effect above releases fnBusy when the new index commits —
  // but ONLY then, because activeFnIdx is its only dependency. If a switch never commits (an
  // exception inside the transition, before setActiveFnIdx, is the realistic way) that effect never
  // re-runs and fnBusy stays true for the rest of the session: every Customize and Resume button
  // disabled, every pill stuck on the progress cursor, and no way out but a reload. A switch that
  // has not landed in three seconds is not one that is still working. In the normal case the effect
  // above has already cleared the flag long before this fires, so this changes nothing.
  useEffect(() => {
    if (!fnBusy) return;
    const t = setTimeout(() => {
      fnBusyStartRef.current = 0;
      setFnBusy(false);
      // ── AND RELEASE THE AUTOSAVE ── (BUG-13)
      // This backstop was built for fnBusy alone, but switchingRef is set true by switchActiveFn on
      // the same click and released ONLY by the effect keyed on activeFnIdx — the very commit that,
      // in the case this backstop exists for, never arrives. So the UI recovered after three
      // seconds while switchingRef stayed true for the rest of the session, and it gates BOTH
      // savers: autoSaveBuild returns immediately on it, and the flush AppSwitcher awaits before
      // navigating to IMS does nothing. Every edit after that point was silently never written —
      // add a Production/Buying item, go to IMS, come back, and it is gone, because no save was
      // ever attempted. Not a lost race: no save at all.
      // Released here on exactly the reasoning the fnBusy release already uses — a switch that has
      // not landed in three seconds is not one that is still working. In the normal case the
      // activeFnIdx effect cleared it long before this fires, so this changes nothing.
      switchingRef.current = false;
    }, 3000);
    return () => clearTimeout(t);
  }, [fnBusy]);
  const isFnSwitching = fnBusy || isPendingFnRender;
  // ── THE AUTOSAVE HAS TO SEE THE SAME "STILL SWITCHING" THE UI DOES ──
  // switchingRef (above) is cleared the moment activeFnIdx commits, but the switch is not finished
  // there: isPendingFnRender stays true while the transition renders, and fnBusy holds the minimum
  // spinner. In that window the ref said "not switching" while the build state was still settling,
  // so an autosave could land on a half-loaded function and write its total as 0 — which is exactly
  // the ₹0 that appeared on the saved-session card before the real figure replaced it.
  // A ref, not the state, because autoSaveBuild is called from timers and listeners that hold a
  // stale closure — the same reason activeFnIdxRef exists.
  const fnSwitchingRef = useRef(false);
  useEffect(() => { fnSwitchingRef.current = isFnSwitching; }, [isFnSwitching]);
  // Dev-only timing for the switch. It re-renders the whole of StudioApp and invalidates ten
  // memo chains, so "it's slow" needs a number before anything is optimised — guessing at the hot
  // spot is how you end up rewriting the wrong thing. Logs the click→committed duration.
  const fnSwitchStartRef = useRef(0);
  useEffect(() => {
    if (!import.meta.env.DEV || !fnSwitchStartRef.current) return;
    const ms = Math.round(performance.now() - fnSwitchStartRef.current);
    fnSwitchStartRef.current = 0;
    console.info(`[ambria] function switch → idx ${activeFnIdx} took ${ms}ms`);
  }, [activeFnIdx]);

  const switchActiveFn = (newIdx) => {
    // Ignore any call while a switch is already in flight (started, not yet committed) — rather
    // than letting the ref bookkeeping below sort out an overlapping switch after the fact. A rapid
    // double-tap on the pill (far more likely on a touchscreen than a mouse click, and the pill's own
    // visual highlight/cursor still takes a render to update) used to be handled by falling through
    // to the snapshot-skip guard a few lines down, which settles correctly on its own in the cases
    // traced by hand, but closing the window here outright removes the need to reason about it at
    // all: every click while switchingRef is true just waits for the in-flight switch to land
    // (switchingRef only clears once activeFnIdx has actually committed — the effect right after its
    // own declaration, a few lines above this function) instead of starting a second one that has to
    // race it.
    if (switchingRef.current) return;
    // committedFnIdxRef, not activeFnIdxRef — see committedFnIdxRef's own comment. activeFnIdxRef can
    // be left pointing at a function whose switch never actually rendered (the busy backstop a few
    // lines down clears switchingRef after 3s even then), and this guard is now the ONLY thing
    // standing between that stale value and snapshotFnRef.current() — which always captures whatever
    // is REALLY on screen — getting filed under the wrong function's slot.
    const curIdx = committedFnIdxRef.current;
    if (newIdx === curIdx) { setFnPending(null); return; }
    fnSwitchStartRef.current = performance.now();
    // Urgent and first: the loading state must be on screen before any of the heavy work below.
    fnBusyStartRef.current = performance.now();
    setFnBusy(true);
    // switchingRef.current is guaranteed false here (the guard above returned otherwise), so this
    // always runs — there is no longer an "already mid-switch" case to skip it for, now that
    // overlapping switches are refused at the top rather than tolerated and reasoned about here.
    const builds = { ...fnBuildsRef.current, [curIdx]: snapshotFnRef.current() };
    fnBuildsRef.current = builds;
    switchingRef.current = true;
    fnSwitchNoSaveRef.current = true;
    activeFnIdxRef.current = newIdx;
    const nextBuilds = builds;
    const target = builds[newIdx] || null;
    setFnPending(newIdx);
    // The ref work above stays OUTSIDE the transition: React may re-run a transition body, and
    // re-snapshotting there would file the wrong build. Everything in here is a plain setState of
    // already-computed values, so a replay is harmless.
    startFnSwitch(() => {
      setFnBuilds(nextBuilds);
      restoreBuildState(target);
      setActiveFnIdx(newIdx);
    });
  };

  // ═══ AUTH- derived helpers (verbatim) ═══
  const [teamData, setTeamData] = useState(DEFAULT_TEAM);
  const [saveError, setSaveError] = useState(null);
  // Event Info's "Load →" was blocked because someone (this user's own other device, or someone
  // else) already has this deal open — same "important, must be read, not a toast" class as the
  // stale-save conflict dialog above it, not a quick confirmation, so it gets the same centred,
  // dimmed-backdrop modal treatment rather than the auto-dismissing toast. { message } or null.
  const [dealOpenConflict, setDealOpenConflict] = useState(null);

  // MEMOIZED, and it has to be. As a plain function this got a new identity on every render, and
  // that identity is load-bearing: saveClientLedger is useCallback(..., [showMsg]), so it churned
  // every render too — and the Deal Check autosave effect lists saveClientLedger in its deps, so
  // THAT re-ran every render. Its cleanup calls doSave(), which writes setDcCache with a fresh
  // `cachedAt: new Date().toISOString()` — a guaranteed state change, hence another render, another
  // effect run, another cleanup. That was React error #185 ("maximum update depth exceeded"): the
  // white screen on returning from Deal Check.
  // It only bit there because the effect early-returns while dcCards is empty, so the cleanup that
  // calls doSave is never registered until Deal Check has generated cards.
  // setToast is a setState function and therefore stable, so [] is correct — nothing this closes
  // over can go stale.
  const showMsg = useCallback((msg, color) => { setToast({ msg, color }); setTimeout(() => setToast(null), 2000); }, []);
  // "Copy a build from an existing client" (CopyBuildModal.jsx) — the modal resolves the picked
  // functions' builds and metadata itself, since it already has clientLedger with every client's
  // sessions loaded (the mount effect bulk-fetches studio_sessions once and attaches `.sessions` to
  // every row — no extra fetch needed here or there). This just merges the result into live state
  // exactly like adding a function by hand (StudioEventInfo.jsx's own "+ Add Function" does the same
  // `setExtraFunctions(prev => [...prev, ...])`), so the normal autosave picks it up with no
  // special-casing. `startIdx` is read from the render closure rather than a ref — a deliberate,
  // infrequent click, not a stale-timer path, so this matches the existing Add-Function pattern.
  // `intoCurrent` (same event type as the function already open here, per CopyBuildModal's own
  // claim logic): loads straight into THIS session's live canvas — no new pill, and the date/
  // venue/shift/pax/palette already set in Event Info are left exactly as they are, since this is
  // the SAME function, just with a different deal's decor dropped in. `newItems` (a different
  // type, or any extra same-type pick beyond the one slot): unchanged, appended as brand-new
  // functions exactly like before.
  const copyBuildsFromClient = useCallback(({ intoCurrent, newItems } = {}) => {
    if (intoCurrent?.build) restoreBuildState(intoCurrent.build);
    const items = Array.isArray(newItems) ? newItems : [];
    if (items.length) {
      const startIdx = 1 + extraFunctions.length;
      setExtraFunctions((prev) => [...prev, ...items.map((it) => it.meta)]);
      setFnBuilds((prev) => {
        const next = { ...prev };
        items.forEach((it, i) => { next[startIdx + i] = it.build; });
        return next;
      });
    }
    const parts = [];
    if (intoCurrent?.build) parts.push("loaded into this session");
    if (items.length) parts.push(`copied ${items.length} as new function${items.length === 1 ? "" : "s"} — switch to ${items.length === 1 ? "it" : "them"} from Browse or Event Info`);
    if (parts.length) showMsg(parts.join(" · "), "green");
  }, [extraFunctions, showMsg]);
  // In-app confirm, so destructive actions ask in the app's own voice instead of a browser alert()
  // (which is unstyled, blocks the whole tab, and on some browsers offers "don't show again").
  // Deliberately does NOT auto-dismiss — an unanswered question must wait for an answer.
  const openConfirm = (cfg) => { confirmToastRef.current = cfg; setConfirmToast(cfg); };
  const askConfirm = (msg, onYes, opts = {}) => openConfirm({ msg, onYes, yesLabel: opts.yesLabel || "Remove", note: opts.note });
  // Promise form, so a call site written as `if (!confirm(...)) return;` keeps its shape when it
  // moves off the browser's native dialog. Resolves false on every dismissal route.
  const askConfirmAsync = useCallback((msg, opts = {}) => new Promise((resolve) => {
    openConfirm({
      msg, note: opts.note, yesLabel: opts.yesLabel || "Confirm", tone: opts.tone,
      onYes: () => resolve(true), onCancel: () => resolve(false),
    });
  }), []);
  // Same dialog with several answers: choices = [{ value, label, primary }], resolves the picked value,
  // or null on Cancel / Escape / the backdrop.
  const askChoiceAsync = useCallback((msg, opts = {}) => new Promise((resolve) => {
    openConfirm({
      msg, note: opts.note, tone: opts.tone, choices: opts.choices || [],
      onChoice: (v) => resolve(v), onCancel: () => resolve(null),
    });
  }), []);
  // Closing the zone-upload review (Back button, Cancel, or the modal's own backdrop click) used to
  // discard it instantly with no confirmation at all — a real gap, since this form can hold several
  // minutes of manually-entered truss/masking dimensions and an edited element list, all held ONLY
  // in this one piece of state (never autosaved; "Apply to Zone" is what actually commits it). A
  // reflexive Back tap (mobile hardware Back, Alt+Left) or a stray click on the dark backdrop threw
  // all of it away in one motion. Confirm only when there's something to lose — an untouched/empty
  // review (AI failed and nothing was typed) can close silently, same as before.
  const closeZoneUploadReview = useCallback(() => {
    const r = zoneUploadReview;
    if (!r) return;
    const hasContent = (Array.isArray(r.elements) && r.elements.length > 0) || (r.dims && Object.keys(r.dims).length > 0);
    if (!hasContent) { setZoneUploadReview(null); return; }
    askConfirm(
      "Discard this zone review? The dimensions, truss/masking rows and element list entered here will be lost — the photo stays uploaded, just not linked to any of this.",
      () => setZoneUploadReview(null),
      { yesLabel: "Discard" }
    );
  }, [zoneUploadReview]);

  // Holds the pending debounced Deal Check save's own flush function, so closeDealCheck (below) can
  // run it immediately instead of losing it — the debounce effect's cleanup (much further down, near
  // Deal Check's own state) only ever CANCELLED the pending timeout on close, silently dropping up to
  // 2.5s of edits every time Deal Check was closed (Back button or ×) shortly after a change.
  // Declared here (not next to the effect that fills it) — and closeDealCheck right after it — so
  // both exist before the Back-button popstate guard below, which references closeDealCheck in its
  // effect's DEPENDENCY ARRAY. That array is a plain expression evaluated the moment this component's
  // render reaches the useEffect(...) call — not deferred like the effect body itself — so a forward
  // reference there throws "Cannot access before initialization" (a real prod crash hit this exact
  // way), unlike a reference inside a callback body that only runs later, once render has finished.
  const flushDcAutosaveRef = useRef(null);
  const dcAutosavePendingRef = useRef(false); // a Deal Check edit is waiting on the 2.5s autosave timer
  // Closes Deal Check, flushing any pending debounced save first (see flushDcAutosaveRef above) —
  // both the Back-button guard and the × button route through this instead of a bare
  // setDcFullPageOpen(false), so neither one silently drops up to 2.5s of unsaved edits on close.
  const closeDealCheck = useCallback(() => {
    if (flushDcAutosaveRef.current) { flushDcAutosaveRef.current(); flushDcAutosaveRef.current = null; }
    setDcFullPageOpen(false);
  }, []);
  // Summary's Apply calls this. Nothing to do when Deal Check is already open — it pushes on its own.
  const syncDeptOpsHeadless = useCallback(() => { if (!dcFullPageOpen) setDcHeadless(true); }, [dcFullPageOpen]);
  // For autoSaveBuild (a []-deps callback), which needs the current one.
  const syncDeptOpsHeadlessRef = useRef(null);
  syncDeptOpsHeadlessRef.current = syncDeptOpsHeadless;
  const finishDcHeadless = useCallback(() => {
    if (flushDcAutosaveRef.current) { flushDcAutosaveRef.current(); flushDcAutosaveRef.current = null; }
    setDcHeadless(false);
  }, []);

  // ── IMS PLANNING FOLLOWS IMS SETTINGS WITHOUT ANYONE OPENING DEAL CHECK ──
  // Crew, kit parts, fabric and every other Dept Ops figure are Deal Check's result, pushed to IMS
  // as a snapshot, so a change made in IMS (a per-labour count, a recipe, a rate, a fixed-venue
  // item, an inventory rental) reached a booked deal only when someone next opened its Deal Check.
  // Opening a booked client now checks that snapshot against the settings and inventory that feed
  // it; if any changed after the last sync, the unseen Deal Check run (syncDeptOpsHeadless) is
  // started right here, once per client per session. The rest is the same run Apply uses, so
  // nothing about what gets pushed to IMS changes — only who has to ask for it.
  const autoSyncedClientsRef = useRef(new Set());
  // The hidden run IMS starts with "Load Deal Check details" (#/studio?sweep=1&order=ID&force=1): that one order is
  // synced even though no setting changed since its last sync.
  const forceSyncOrderRef = useRef((() => { try { const h = window.location.hash; const m = /[?&]force=1/.test(h) && /[?&]order=([^&]+)/.exec(h); return m ? decodeURIComponent(m[1]) : null; } catch { return null; } })());
  // The startup sweep (further down, after startNewDeal) walks every stale booked deal through this
  // same auto-sync. `id` is the deal it has open right now; autoSaveBuild stands still while it is
  // set — a sweep never edits anything, and its screen is covered so nobody else can.
  const sweepRef = useRef({ id: null, stop: false });
  const [sweepInfo, setSweepInfo] = useState(null);
  useEffect(() => {
    if (!activeClientId || dcFullPageOpen || dcHeadless) return;
    if (autoSyncedClientsRef.current.has(activeClientId)) return;
    const cli = (clientLedger || []).find(c => c.id === activeClientId);
    if (!cli || cli.status !== "booked") return;
    const eo = eventOrderFor(eventOrders, activeClientId, clientName);
    if (!eo || !eo.deptSyncedAt) return; // never synced yet — the first Deal Check open does that
    // Only once this client's build has actually loaded: a run over a build that is still empty
    // would push an empty plan to IMS. Until then this effect just waits for the next change.
    if (!Object.values(zoneElements || {}).some(a => Array.isArray(a) && a.length > 0)) return;
    autoSyncedClientsRef.current.add(activeClientId); // once per client per session
    const clientId = activeClientId;
    (async () => {
      try {
        // Let the deal's own screen paint first: the hidden Deal Check run is a full pricing + load of its own, and starting
        // it in the same moment the build renders made opening a booked deal feel stuck. The startup sweep keeps its pace.
        // If the salesperson has moved to another client by then, nothing runs (and this one can sync on its next open).
        if (!sweepRef.current.id) {
          await new Promise((r) => (typeof window.requestIdleCallback === "function" ? window.requestIdleCallback(() => r(), { timeout: 2500 }) : setTimeout(r, 1200)));
          if (activeClientIdRef.current !== clientId) { autoSyncedClientsRef.current.delete(clientId); return; }
        }
        const latest = await latestPlanningInputStamp();
        if (!latest) return;
        // A minute of slack: the sync's own write lands moments after the run it belongs to.
        if (latest > Number(eo.deptSyncedAt) + 60000 || planningSnapshotOutdated(eo) || (forceSyncOrderRef.current && forceSyncOrderRef.current === eo.id)) syncDeptOpsHeadlessRef.current?.();
      } catch { /* best effort — a missed auto-sync only means the old manual way */ }
    })();
  }, [activeClientId, clientLedger, eventOrders, zoneElements, dcFullPageOpen, dcHeadless, clientName]);

  // Same race as the Studio↔IMS switcher (AppSwitcher.jsx): logout() flips `user` to null, which
  // unmounts this whole component on the next render — a bare call here gave a pending edit no
  // chance to actually reach the server before that happened. Reuses the same registered flush
  // (build session + Deal Check draft), capped so a slow/broken save can't hang the logout click.
  const doLogout = async () => {
    await Promise.race([flushBeforeReload(), new Promise((resolve) => setTimeout(resolve, 2500))]);
    logout();
  };
  // Role check is case-insensitive: the shared users table uses "Admin" (capital), the
  // reference Studio used "admin". Also honor the seeded u_admin id.
  // Role check is case-insensitive: the shared users table uses "Admin" (capital), the
  // reference Studio used "admin". Also honor the seeded u_admin id.
  const isAdmin = (authUser?.role || "").toLowerCase() === "admin" || authUser?.id === "u_admin";

  // Per-role Studio permissions — configured from IMS → Admin → Users → Tab Access
  // (settings.roleTabs[role].studio.perms, the 8 canX flags). Drives hasPerm below.
  const [studioRoleTabs, setStudioRoleTabs] = useState({});
  useEffect(() => { (async () => { try { const v = await kvGet("roleTabs"); const p = typeof v === "string" ? JSON.parse(v) : v; if (p && typeof p === "object") setStudioRoleTabs(p); } catch { /* ignore */ } })(); }, []);
  // Role's Studio tab/sub-tab config (settings.roleTabs[role].studio). null = admin (all).
  // Unconfigured non-admin defaults to deal-builder only (matches the reference 'sales' default).
  const studioCfg = useMemo(() => {
    if (isAdmin) return null;
    return studioRoleTabs?.[authUser?.role]?.studio || { tabs: ["design"], subTabs: {} };
  }, [isAdmin, studioRoleTabs, authUser]);
  const hasStudioTab = useCallback((t) => isAdmin || (studioCfg?.tabs || []).includes(t), [isAdmin, studioCfg]);
  const studioSub = useCallback((parent, sub) => {
    if (isAdmin) return true;
    if (!(studioCfg?.tabs || []).includes(parent)) return false;
    // "Restriction is opt-in" (RoleAccessModal.jsx's own documented rule for this exact data shape):
    // an absent/empty subTabs[parent] means every child is visible — no admin action ever
    // restricted anything under this tab, so nothing under it should be hidden. This used to
    // require an explicit grant unconditionally, silently hiding Deal Check (and viewpricing/
    // export, and every Settings sub-view routed through here) for every Sales role that was
    // never individually hand-customized, since the seeded default is {tabs:["design"],subTabs:{}}
    // — an admin who never touched a single toggle for a role saw "nothing restricted" and
    // reasonably assumed everything was visible, while this returned false for all of it.
    // studioLibraryAllowed already implements this same rule correctly; this brings dealcheck/
    // viewpricing/export/settings-sub-views (everything else routed through studioSub) in line
    // with it instead of being the one path still requiring an explicit grant.
    const subs = studioCfg?.subTabs?.[parent];
    if (!subs || subs.length === 0) return true;
    return subs.includes(sub);
  }, [isAdmin, studioCfg]);
  // Which Studio Settings sub-views (venues/tags/clients/calendar/users/zones/palettes/
  // priority) this role can see — consumed by ManageSettings.
  const studioSettingsAllowed = useCallback((view) => isAdmin || studioSub("settings", view), [isAdmin, studioSub]);
  // Which Library & content sub-views (images/videos/corrections) this role can see. If the
  // Library tab is granted but no sub-tabs are explicitly picked, all three are allowed (matches
  // the IMS supply-tab convention: no sub-config = full access to the granted tab).
  const studioLibraryAllowed = useCallback((view) => {
    if (isAdmin) return true;
    if (!(studioCfg?.tabs || []).includes("library")) return false;
    const subs = studioCfg?.subTabs?.library;
    if (!subs || subs.length === 0) return true;
    return subs.includes(view);
  }, [isAdmin, studioCfg]);
  // Map the reference's canX perm flags onto the Studio tab/sub-tab grants. Every existing
  // hasPerm("canX") call site across Studio/views/manage keeps working through this.
  const hasPerm = useCallback((perm) => {
    if (isAdmin) return true;
    switch (perm) {
      case "canViewPricing": return studioSub("design", "viewpricing");
      case "canExport": return studioSub("design", "export");
      case "canEditEvents":
      case "canManageLibrary": return hasStudioTab("library");
      case "canManageTemplates": return hasStudioTab("settings");
      case "canManageVenues": return studioSub("settings", "venues");
      case "canManageUsers": return studioSub("settings", "users");
      default: {
        const p = authUser?.perms;
        if (Array.isArray(p)) return p.includes(perm);
        return p?.[perm] === true;
      }
    }
  }, [isAdmin, studioSub, hasStudioTab, authUser]);

  const userVenueScope = useMemo(() => {
    if (!authUser) return "all";
    return teamData[authUser.id]?.venueScope || "all";
  }, [authUser, teamData]);

  // Deal builder (studio mode) is always available to anyone with Studio access — it's the
  // base. Manage mode appears only if the role has a manage area (library/pricing/settings).
  const canManageAny = isAdmin || hasStudioTab("library") || hasStudioTab("settings");
  useEffect(() => { if (mode === "manage" && !canManageAny) setMode("studio"); }, [mode, canManageAny]);

  // Edit Access/per-user override, Admin → Users & Roles → the Edit/Delete half of tabAccess.js's
  // per-tab model (design/library/settings) — separate from hasStudioTab/studioSub above, which
  // only ever answer "is this tab/sub-tab VISIBLE", never "can I change anything in it".
  // Deliberately reads the RAW `user` from useAuth(), not the reshaped `authUser` above: authUser
  // is trimmed to {id,name,role,perms} and never carries tabOverride/tab_override, so hasTabPerm's
  // per-user override would silently never apply if called with it. `settings` here is a tiny
  // shim — tabAccess.js only ever reads `settings.roleTabs`, and Studio's own equivalent of that
  // is the `studioRoleTabs` state already loaded above (IMS's settings.roleTabs, same key).
  const studioTabSettings = useMemo(() => ({ roleTabs: studioRoleTabs }), [studioRoleTabs]);
  const canStudio = useCallback((tab, action) => isAdmin || hasTabPerm(user, studioTabSettings, "studio", tab, action), [isAdmin, user, studioTabSettings]);
  // A couple of callbacks below (persistDcKitEditsNow) deliberately keep an EMPTY dependency array
