  const holdersOnDate = useCallback((itemId, date, blocksDetailForDate) => {
    if (!itemId || !date) return [];
    const eo = eventOrderFor(eventOrders, activeClientId, clientName);
    const own = new Set([eo?.id, ...ownEventOrderIds(eventOrders, activeClientId, clientName)].filter(Boolean));
    const byEvent = new Map();
    (blocksDetailForDate?.[itemId] || []).forEach((b) => {
      if (!b || own.has(b.eventId) || !(Number(b.qty) > 0)) return;
      byEvent.set(b.eventId, (byEvent.get(b.eventId) || 0) + Number(b.qty));
    });
    return [...byEvent.entries()].map(([eventId, qty]) => {
      const o = (eventOrders || []).find((x) => x.id === eventId) || null;
      const cli = o ? (clientLedger || []).find((c) => c && c.id === o.clientId) : null;
      const fd = (Array.isArray(o?.functionsDetail) ? o.functionsDetail : []).find((f) => String(f?.fnDate || f?.date || "") === date);
      return {
        client: o?.clientName || cli?.name || "Unknown event",
        cancelled: o?.status === "cancelled",
        salesperson: o?.salesperson || cli?.bookedBy || cli?.createdBy || "",
        venue: fd?.fnVenue || fd?.venue || o?.venue || cli?.venue || "",
        qty,
      };
    }).sort((a, b) => b.qty - a.qty);
  }, [eventOrders, activeClientId, clientName, clientLedger]);
  const freeOnActiveDate = useCallback((it) => {
    if (!it) return { free: 0, why: "" };
    const eo = eventOrderFor(eventOrders, activeClientId, clientName);
    const ownIds = [eo?.id, ...ownEventOrderIds(eventOrders, activeClientId, clientName)].filter(Boolean);
    const netted = netOwnReservedBlocksLive(activeBlocksForDate, it.id, activeBlocksDetailForDate, ownIds);
    const venueName = activeFnMeta?.venue || venue || "";
    const total = Number(it.qty ?? it.qtyOwned) || 0;
    const _fvOverlap = fixedVenueOverlapOnDate(fvCfgForRepeat, venueName, it, activeBlocksDetailForDate?.[it.id], eventOrders, { excludeEventIds: ownIds, date: activeFnMeta?.date || clientDate });
    const free = combineAvailability(total, getStudioAvailable(it, netted), availableAtVenue(fvCfgForRepeat, venueName, it), _fvOverlap);
    const own = new Set(ownIds);
    const fixed = lockedAtFixedVenues(fvCfgForRepeat, venueName, it);
    const holders = (activeBlocksDetailForDate?.[it.id] || []).filter((b) => b && !own.has(b.eventId) && Number(b.qty) > 0)
      .map((b) => { const o = (eventOrders || []).find((x) => x.id === b.eventId); return `${o?.clientName || "an unknown event"}${o?.status === "cancelled" ? " (cancelled - not released)" : ""} ${b.qty}`; });
    const imsBlocked = Number(it.blocked) || 0;
    const why = [`Stock: ${total}`,
      fixed.length ? `Kept at fixed venues: ${fixed.map((f) => `${f.name} ${f.qty}`).join(", ")}` : "",
      imsBlocked > 0 ? `Blocked in IMS (all dates): ${imsBlocked}` : "",
      holders.length ? `Booked this date by: ${holders.join(", ")}` : "",
      `Free: ${Math.max(0, Math.floor(free))}`].filter(Boolean).join(String.fromCharCode(10));
    // reason: the short line Build prints under a 0-free item - who holds it, without hovering
    const reason = [holders.length ? `Booked by ${holders.join(", ")}` : "", fixed.length ? `Kept at ${fixed.map((f) => `${f.name} ${f.qty}`).join(", ")}` : "", imsBlocked > 0 ? `${imsBlocked} blocked in IMS` : "", total <= 0 ? "No stock in IMS" : ""].filter(Boolean).join(" · ");
    return { free, why, reason };
  }, [eventOrders, activeClientId, clientName, activeBlocksForDate, activeBlocksDetailForDate, activeFnMeta, venue, fvCfgForRepeat, clientDate]);
  // Shared SMB/flat rate resolution — the one place `getElPrice`, `getElPriceForFn`, and
  // `calcFullEventCost` all resolve a rate-card item's base rate for an element's size, now with
  // the sub-category scaling factor applied. Previously duplicated verbatim in all three
  // functions; consolidated here so the factor only needs wiring in once.
  const resolveRcRate = useCallback((rc, sz) => {
    let realRate = 0, artRate = 0;
    if (rcIsSMB(rc)) {
      if (sz === "S" || sz === "SMALL") { realRate = rc.inhouseS || 0; artRate = rc.artificialS || 0; }
      else if (sz === "B" || sz === "BIG" || sz === "LARGE" || sz === "PREMIUM" || sz === "HEAVY") { realRate = rc.inhouseB || 0; artRate = rc.artificialB || 0; }
      else { realRate = rc.inhouseM || 0; artRate = rc.artificialM || 0; }
    } else {
      realRate = rc.inhouseFlat || 0;
      artRate = rc.artificialFlat || 0;
    }
    const factor = rcScalingFactor(rc);
    return { realRate: realRate * factor, artRate: artRate * factor };
  }, [rcScalingFactor]);

  const buildZoneConfig = (zk, photoDims) => {
    const zm = zoneMeta[zk]; if (!zm || !zm.dimFields?.length) return null;
    const d = photoDims || {};
    // Extra truss/platform rows (zoneUploadReview.dims.trussRows/platformRows, Library-shape) →
    // zoneConfig-shape extraTrussRows/extraPlatformRows, same conversion "row 0" gets below.
    const mapTrussRow = (row) => {
      const rDims = {};
      if (row.trussL) rDims.L = row.trussL;
      if (row.trussW) rDims.W = row.trussW;
      if (row.trussH) rDims.H = row.trussH;
      const numRDims = [rDims.L, rDims.W, rDims.H].filter(v => (v || 0) > 0).length;
      return {
        id: row.id, dims: rDims, trT: numRDims >= 3 ? "box" : (zm.defaultTruss || "singleU"),
        trussQty: Number(row.trussQty) === 0 ? 0 : Math.max(1, Number(row.trussQty) || 1),
        trussFrontExt: Number(row.trussFrontExt) || 0,
        trussFrontExtH: Number(row.trussFrontExtH) || 0,
        mkOn: !!row.mkT, mkT: row.mkT || null, mkWalls: row.mkWalls || {},
        trussMaterial: row.trussMaterial ?? null, drapeDensity: row.drapeDensity ?? null,
        customCeilingItemId: row.customCeilingItemId ?? null, customCeilingQty: row.customCeilingQty ?? null, customMaskingItemId: row.customMaskingItemId ?? null,
      };
    };
    const mapPlatformRow = (row) => ({
      id: row.id, plH: row.plH || null, plHft: row.plHft ?? null, cpT: row.cpT ?? null,
      floorDims: (row.floorL || row.floorW) ? { L: row.floorL || 0, W: row.floorW || 0 } : {},
    });
    const dims = {};
    if (d.trussL) dims.L = d.trussL;
    if (d.trussW) dims.W = d.trussW;
    if (d.trussH) dims.H = d.trussH;
    if (d.trussL || d.trussW) dims.S = d.trussL || d.trussW;
    zm.dimFields.forEach(f => { if (dims[f] === undefined) dims[f] = 0; });
    const floorDims = {};
    if (d.floorL) floorDims.L = d.floorL;
    if (d.floorW) floorDims.W = d.floorW;
    const hasDims = (dims.L || 0) > 0 || (dims.W || 0) > 0 || (dims.H || 0) > 0 || (dims.S || 0) > 0;
    const numDims = [dims.L, dims.W, dims.H].filter(v => (v || 0) > 0).length;
    const trT = hasDims ? (numDims >= 3 ? "box" : (zm.defaultTruss || "singleU")) : (zm.defaultTruss || null);
    return {
      dims: hasDims ? dims : Object.fromEntries(zm.dimFields.map(f => [f, 0])),
      floorDims: Object.keys(floorDims).length ? floorDims : (hasDims ? { ...dims } : {}),
      trT, mkOn: !!d.mkT, mkT: d.mkT || null, mkWalls: d.mkWalls || {},
      plH: d.plH || null, plHft: d.plHft ?? null, cpT: d.cpT ?? null,
      trussMaterial: d.trussMaterial ?? null, drapeDensity: d.drapeDensity ?? null,
      customCeilingItemId: d.customCeilingItemId ?? null, customCeilingQty: d.customCeilingQty ?? null, customMaskingItemId: d.customMaskingItemId ?? null,
      // Carry truss quantity + box front-extension tagged on the library photo through to Build.
      trussQty: Number(d.trussQty) === 0 ? 0 : Math.max(1, Number(d.trussQty) || 1),
      trussFrontExt: Number(d.trussFrontExt) || 0,
      trussFrontExtH: Number(d.trussFrontExtH) || 0,
      extraTrussRows: (d.trussRows || []).map(mapTrussRow),
      extraPlatformRows: (d.platformRows || []).map(mapPlatformRow),
    };
  };

  const applyFloralRatio = useCallback((unitPrice, rc) => unitPrice, []);

  // Floral recipe dataset (flowerPatterns, mandi prices, artificial-mix rates, markup) — loaded on
  // mount so the Build view can auto-derive floral rates without the user first opening Deal Check
  // (which fetches the full dealCheckData). floralArtUnitRate/patternExtra prefer dealCheckData
  // (date-aware, fresher) and fall back to this. Also re-fetched live below whenever IMS edits any
  // of these settings rows — a recipe/mandi-price/markup change should reach Studio instantly, not
  // just on next reload, same as inventory item edits already do (see the "inventory" table
  // subscription below).
  const FLORAL_DATA_KEYS = [
    "artificialFlowerRatePerKg", "artificialFlowerBunchesPerKg",
    "artificialGreenRatePerKg", "artificialGreenBunchesPerKg", "defaultStudioMarkup",
    "fixedVenueSubcatDiscount", "agencyFeePct", "datePricing",
  ];
  const loadStudioFloralData = useCallback(async () => {
    try {
      // truss_inventory alongside settings, same parallel fetch shape — it's one row (key "main"),
      // not the 600+-row `inventory` table, so it costs nothing extra to load on mount. Needed so the
      // fixed-venue pillar/beam discount (calcStructCost's trussInv param) can compute before Deal
      // Check has ever been opened — dealCheckData?.trussInv used to be the only source, so Build's/
      // Summary's own total silently omitted this discount (showing a HIGHER total) until Deal Check
      // loaded it, then stayed lower afterward — the other half of the "total changes after opening
      // Deal Check" bug, alongside the agencyFeePct/fixedVenues gap fixed above. fixedVenues itself
      // comes from the `fixed_venues` TABLE (migration 038), mandiCatalogue from `mandi_flowers`
      // (migration 039), and flowerPatterns from `flower_patterns` (migration 040) — none of them
      // are this settings-keys fetch any more.
      const [{ data }, trussInvRows, fixedVenueRows, mandiRows, patternRows, markedDateRows, trussAllocRows, platformAllocRows, battaAllocRows] = await Promise.all([
        supabase.from("settings").select("key,value").in("key", FLORAL_DATA_KEYS),
        fetchAll("truss_inventory").catch(() => []),
        fetchAll("fixed_venues").catch(() => []),
        fetchAll("mandi_flowers").catch(() => []),
        fetchAll("flower_patterns").catch(() => []),
        fetchAll("date_pricing_overrides").catch(() => []),
        // truss_allocations/platform_allocations/batta_allocations — the SAME per-date pool IMS's own
        // Planning dashboards read (see trussEngine.js/platformEngine.js/battaEngine.js), fetched here
        // too so markSold's pre-sale stock gate (scanTrussStockShortage, below) can check this build's
        // own truss/platform/batta demand against real stock BEFORE committing the sale, not just see
        // a shortage after the fact on the IMS side.
        fetchAll("truss_allocations").catch(() => []),
        fetchAll("platform_allocations").catch(() => []),
        fetchAll("batta_allocations").catch(() => []),
      ]);
      // date -> {events, ...pool} — same shape IMS.jsx's own rowToAlloc builds (soft-hold rows are
      // never written any more, per truss_allocations' own comment, but dropped here defensively too).
      const rowsToAllocMap = (rows) => Object.fromEntries((rows || []).map((r) => [r.date, { ...(r.pool || {}), date: r.date, events: (r.events || []).filter((ev) => ev?.state !== "soft") }]));
      const s = {};
      (data || []).forEach(r => { let v = r?.value; for (let i = 0; i < 2; i++) { if (typeof v === "string") { try { v = JSON.parse(v); } catch { break; } } } s[r.key] = v; });
      let trussInv = null;
      const trussMain = Array.isArray(trussInvRows) ? trussInvRows.find(r => r.key === "main") : null;
      let tv = trussMain?.data;
      for (let i = 0; i < 2; i++) { if (typeof tv === "string") { try { tv = JSON.parse(tv); } catch { break; } } }
      if (tv && typeof tv === "object" && tv.pillars) trussInv = tv;
      setStudioFloralData({
        flowerPatterns: assembleFlowerPatternsFromRows(patternRows),
        mandiCatalogue: assembleMandiCatalogueFromRows(mandiRows),
        artificialFlowerRatePerKg: typeof s.artificialFlowerRatePerKg === "number" ? s.artificialFlowerRatePerKg : 50,
        artificialFlowerBunchesPerKg: (typeof s.artificialFlowerBunchesPerKg === "number" && s.artificialFlowerBunchesPerKg > 0) ? s.artificialFlowerBunchesPerKg : 16,
        artificialGreenRatePerKg: typeof s.artificialGreenRatePerKg === "number" ? s.artificialGreenRatePerKg : 40,
        artificialGreenBunchesPerKg: (typeof s.artificialGreenBunchesPerKg === "number" && s.artificialGreenBunchesPerKg > 0) ? s.artificialGreenBunchesPerKg : 23,
        defaultStudioMarkup: Number(s.defaultStudioMarkup ?? 3) || 3,
        fixedVenues: assembleFixedVenuesFromRows(fixedVenueRows),
        fixedVenueSubcatDiscount: (s.fixedVenueSubcatDiscount && typeof s.fixedVenueSubcatDiscount === "object") ? s.fixedVenueSubcatDiscount : {},
        // Same reason fixedVenues lives here and not only in dealCheckData: eventGrandTotal/grandTotal/
        // buildCombinedCostSheetData (Build's own live total, Summary's hero, the cost sheet) all need
        // the REAL configured fee before Deal Check has ever been opened — dealCheckData stays null
        // until then, and these totals used to silently fall back to a hardcoded 20% in the meantime,
        // then visibly jump once Deal Check's fetch landed and stayed jumped (dealCheckData persists
        // after Deal Check closes). This lightweight settings-only fetch closes that gap.
        agencyFeePct: typeof s.agencyFeePct === "number" ? s.agencyFeePct : DEFAULT_AGENCY_FEE_PCT,
        // Same reasoning as agencyFeePct/fixedVenues above — Category Multipliers (IMS → Calendar →
        // Date Pricing Config) must scale the guest-facing rental price before Deal Check has ever
        // been opened too, not just once dealCheckData's own copy has loaded.
        // markedDates is the `date_pricing_overrides` TABLE (migration 046) now — a sub-field merge
        // on top, same reasoning as fixedVenues/mandiCatalogue/flowerPatterns above.
        datePricing: { ...((s.datePricing && typeof s.datePricing === "object") ? s.datePricing : SETTINGS_DEFAULTS.datePricing), markedDates: assembleMarkedDatesFromRows(markedDateRows) },
        trussInv,
        trussAlloc: rowsToAllocMap(trussAllocRows),
        platformAlloc: rowsToAllocMap(platformAllocRows),
        battaAlloc: rowsToAllocMap(battaAllocRows),
      });
    } catch { /* ignore — floral auto-derive falls back to flat rate */ }
  }, []);
  // What every realtime change (9 tables) and every return to the tab calls: a burst of changes - a sale writes several
  // allocation rows at once - made one full 9-table reload per row, overlapping. Now a burst settles into ONE reload,
  // and a change arriving while a reload is running gets one more after it, so the last state is always read.
  const floralRefreshRef = useRef({ timer: null, running: false, again: false });
  const refreshStudioFloralData = useCallback(() => {
    const st = floralRefreshRef.current;
    const run = async () => {
      if (st.running) { st.again = true; return; }
      st.running = true;
      try { await loadStudioFloralData(); } finally {
        st.running = false;
        if (st.again) { st.again = false; run(); }
      }
    };
    clearTimeout(st.timer);
    st.timer = setTimeout(run, 300);
  }, [loadStudioFloralData]);
  useEffect(() => { loadStudioFloralData(); }, [loadStudioFloralData]);

  // Auto-derived artificial rate PER UNIT for a floral recipe element = Σ(recipe flowers × artificial
  // bunches-per-unit) × ₹/bunch × studio markup. Mirrors calcFnFloralSourcingCost's artificial cost so
  // the client charge for the artificial portion is never ₹0 just because a flat rate wasn't typed in.
  // Returns null when the element has NO recipe (caller then falls back to the flat rate-card artificial rate).
  const floralArtUnitRate = useCallback((rc, size) => {
    const src = sharedFloralSettings;
    const fp = src.flowerPatterns || [];
    if (!fp.length) return null;
    const mc = src.mandiCatalogue || [];
    const afRate = Number(src.artificialFlowerRatePerKg ?? 50);
    const afBPK = Number(src.artificialFlowerBunchesPerKg ?? 16) || 16;
    const agRate = Number(src.artificialGreenRatePerKg ?? 40);
    const agBPK = Number(src.artificialGreenBunchesPerKg ?? 23) || 23;
    const markup = Number(src.defaultStudioMarkup ?? 3) || 3;
    const tn = String(rc?.name || "").toLowerCase().trim();
    let pat = fp.find(p => String(p?.name || "").toLowerCase().trim() === tn);
    if (!pat) pat = fp.find(p => { const n = String(p?.name || "").toLowerCase().trim(); return n && tn && (n.includes(tn) || tn.includes(n)); });
    if (!pat) return null;
    const sz = String(size || "").toUpperCase();
    const sk = rcIsSMB(rc) ? (sz === "S" || sz === "SMALL" ? "small" : (sz === "B" || sz === "BIG" || sz === "LARGE" || sz === "PREMIUM" || sz === "HEAVY" ? "big" : "medium")) : "medium";
    const sizes = pat.sizes || {};
    let comp = sizes[sk] || sizes.medium; if (!comp && sk === "big" && sizes.large) comp = sizes.large;
    if (!comp && Object.keys(sizes).length) comp = sizes[Object.keys(sizes)[0]];
    if (!comp || !Array.isArray(comp.flowers)) return null;
    let cost = 0, mappedFinal = 0, realOnlyCost = 0, invItemCost = 0;
    comp.flowers.forEach(fl => {
      if (fl.invItemId) {
        // A direct IMS Inventory ingredient (no mandi-flower counterpart at all) — mirrors
        // flowerHelpers.js's floralPatternUnitRates: priced raw (no rate_card_categories scaling
        // factor — the recipe's own Markup field owns this, not the general Studio pricing rules)
        // and marked up by the same `markup` this function's real callers use, so it contributes
        // its full cost here instead of silently dropping out (resolveMandiFlower(undefined) would
        // return null, `ft` would default to "flower", and it would be priced as an artificial
        // bunch estimate of ₹0 — this was the same class of bug the Real Only fix above closes).
        const item = (imsInventory || []).find(i => i.id === fl.invItemId);
        const rawPrice = item ? (Number(item.price ?? item.rentalCost) || 0) : 0;
        invItemCost += (Number(fl.qty) || 0) * rawPrice;
        return;
      }
      const res = resolveMandiFlower(fl.flowerId, mc);
      const parent = res?.parent || null;
      const ft = parent?.flowerType || (parent?.isGreen ? "green" : "flower");
      if (ft === "real_only") {
        // No artificial substitute exists — this flower is bought at mandi rate regardless of the
        // element's real/artificial slider, so its cost must land identically on both sides of the
        // blend (mirrors flowerHelpers.js's floralPatternUnitRates) instead of vanishing to ₹0 as
        // real% drops. Marked up by the SAME `markup` the real side uses, tracked separately from
        // `cost` so it isn't also run through the bunches-per-kg artificial rate.
        realOnlyCost += (Number(fl.qty) || 0) * (res?.price || 0);
        return;
      }
      if (ft === "mapping") {
        // Artificial version is a SPECIFIC inventory item — priced LIVE the same way every other
        // inventory item in Studio is (item.price × its sub-category's scaling_factor), not the
        // one-time artificialMapPrice/Cost snapshot taken when it was mapped (that's just the raw
        // pre-factor price, captured once — stale the moment either number changes afterward).
        // Falls back to the snapshot only if the mapped item can no longer be found.
        const invItem = (imsInventory || []).find(i => i.id === parent?.artificialMapItemId);
        const liveRate = invItem ? priceForInvItem(invItem, rcFactorByKey, imsInventory) : (Number(parent?.artificialMapPrice) || Number(parent?.artificialMapCost) || 0);
        mappedFinal += (Number(fl.qty) || 0) * liveRate;
        return;
      }
      const bpu = Number(parent?.artificialBunchesPerUnit) || 0;
      const bunches = (Number(fl.qty) || 0) * bpu;
      cost += bunches * (ft === "green" ? agRate / agBPK : afRate / afBPK);
    });
    return Math.round(cost * markup + mappedFinal + realOnlyCost * markup + invItemCost * markup);
  }, [dealCheckData, studioFloralData, imsInventory, rcFactorByKey]);

  // Fixed extra cost (pot / base / frame) for a floral recipe element+size, added AFTER markup (flat ₹).
  const patternExtra = useCallback((rc, size) => {
    const fp = sharedFloralSettings.flowerPatterns;
    if (!fp.length) return 0;
    const tn = String(rc?.name || "").toLowerCase().trim();
    let pat = fp.find(p => String(p?.name || "").toLowerCase().trim() === tn);
    if (!pat) pat = fp.find(p => { const n = String(p?.name || "").toLowerCase().trim(); return n && tn && (n.includes(tn) || tn.includes(n)); });
    if (!pat) return 0;
    const sz = String(size || "").toUpperCase();
    const sk = rcIsSMB(rc) ? (sz === "S" || sz === "SMALL" ? "small" : (sz === "B" || sz === "BIG" || sz === "LARGE" || sz === "PREMIUM" || sz === "HEAVY" ? "big" : "medium")) : "medium";
    const sizes = pat.sizes || {};
    let comp = sizes[sk] || sizes.medium; if (!comp && sk === "big" && sizes.large) comp = sizes.large;
    if (!comp && Object.keys(sizes).length) comp = sizes[Object.keys(sizes)[0]];
    return Number(comp?.extraCost) || 0;
  }, [dealCheckData, studioFloralData]);

  // venueName (optional): defaults to the CURRENTLY ACTIVE function's own venue (activeFnMeta.venue
  // already resolves that — function 0 or whichever extraFunctions entry is active) — every
  // existing caller of getElPrice/calcElsCost prices the active function's live canvas, so this
  // default is always correct for them without having to pass it explicitly at each call site.
  const getElPriceRaw = useCallback((el, zc, opts, venueName) => {
    if (isFoc(el)) return FOC_PRICE; // left at the venue from a previous event — billed nothing, guest or internal
    if (el.invId) return getElPriceFromInventory(el, { ...opts, zc, venueName: venueName ?? activeFnMeta.venue }); // IMS inventory-sourced element — Rate Card never consulted
    if (el.mandiId) return floralRepeatDiscount(getElPriceFromMandi(el), el, zc); // raw mandi commodity (e.g. Loose Petals), no recipe/inventory
    if (el.patternId) return floralRepeatDiscount(getElPriceFromPattern(el), el, zc); // pure flower-recipe element, no inventory item
    const rc = rcItems.find(i => i.name.toLowerCase() === (el.name || "").toLowerCase());
    if (!rc) return { rc: null, unitPrice: 0, lineCost: 0, area: 0, warning: null, isFloralBlend: false, realPct: null };
    const isFloral = (rc.cat || "").toLowerCase() === "florals";
    const mode = getFloralMode(rc, rcFloralModeByKey);
    const sz = (el.size || "").toUpperCase();
    const { realRate, artRate } = resolveRcRate(rc, sz);
    let up = 0, realPct = null;
    if (isFloral) {
      let modeDefault;
      if (mode === "real") modeDefault = 100;
      else if (mode === "artificial") modeDefault = 0;
      else modeDefault = Math.max(0, Math.min(100, 100 - floralRatio));
      realPct = (typeof el.realPct === "number") ? Math.max(0, Math.min(100, el.realPct)) : modeDefault;
      // Recipe elements → auto-derive the artificial rate (so it's never ₹0); props with no recipe use the flat rate.
      const autoArt = floralArtUnitRate(rc, el.size);
      const effArt = (autoArt != null) ? autoArt : (artRate > 0 ? artRate : realRate); // recipe → auto-derive; else the flat artificial rate; else fall back to the real/flat rate so a flat-priced floral (e.g. an accessory on 100% artificial with no recipe/artificial rate) never shows ₹0
      up = Math.round(realPct / 100 * realRate + (100 - realPct) / 100 * effArt);
      if (rc.unit !== "truss_sqft") up += patternExtra(rc, el.size); // pot/base extra (per pc), added after markup
    } else {
      up = realRate;
    }
    if (rc.unit === "truss_sqft") {
      const d = (zc && zc.dims) || {};
      const fd = (zc && zc.floorDims) || d;
      let area = 0, warning = null;
      if (zc && zc.trT === "box") {
        area = (d.L || 0) * (d.W || 0);
      } else {
        area = (fd.L || 0) * (fd.W || 0);
        if (area > 0) warning = "⚠ No box truss — using floor area; confirm venue has pre-built structure for hangings";
        else warning = "⚠ Add box truss or zone dimensions for hanging area";
      }
      const tr = { rc, unitPrice: up, lineCost: area * up, area, warning, isFloralBlend: isFloral, realPct };
      return isFloral ? floralRepeatDiscount(tr, el, zc) : tr;
    }
    const r = { rc, unitPrice: up, lineCost: (el.qty || 0) * up, area: 0, warning: null, isFloralBlend: isFloral, realPct };
    return isFloral ? floralRepeatDiscount(r, el, zc) : r;
  }, [rcItems, getFloralMode, rcFloralModeByKey, floralRatio, floralArtUnitRate, patternExtra, resolveRcRate, getElPriceFromInventory, getElPriceFromPattern, getElPriceFromMandi, activeFnMeta, hideDiscountFromClient]);
  // guestPriceMultiplier + dateCategoryMultiplierFor(activeFnMeta.date) applied once, here, on top
  // of whichever branch above priced the element — scales unitPrice/lineCost only, leaving area/
  // warning/availability/realPct untouched. activeFnMeta.date is whichever function's tab is
  // currently open in Build — clientDate is NOT that: it is always function 0's own date
  // specifically (restoreBuildState, run on every function-tab switch, never touches it), so a
  // deal's 2nd+ function priced here at clientDate's date-category instead of its own — e.g. a
  // Filler-dated function 1 and a Kings-dated function 2 both silently priced at Filler while
  // function 2 was the one open in Build.
  const getElPrice = useCallback((el, zc, opts, venueName) => {
    const r = getElPriceRaw(el, zc, opts, venueName);
    const mult = guestPriceMultiplier * (isFlowerPriced(el, r) ? 1 : dateCategoryMultiplierFor(activeFnMeta.date));
    if (mult === 1) return r;
    // r.shortCost (getElPriceFromInventory only — every other branch has none, so shortCost is
    // always 0 there and this reduces to the exact same blanket multiplication as before) is the
    // RAW, pre-multiplier cost of a true shortfall — units nothing exists for anywhere, genuinely
    // fresh production. Owner ask: that cost-basis figure must not move with the date's King's/
    // Perfect/Filler market-rental category, only with the guest-price dial (a manual salesperson
    // setting, not a date rule) — so dateCategoryMultiplierFor is scoped to the owned/discount-
    // eligible portion of lineCost only, never the shortfall's own contribution to it.
    const shortCost = Number(r.shortCost) || 0;
    if (shortCost <= 0) {
      return { ...r, unitPrice: r.unitPrice * mult, fullUnitPrice: r.fullUnitPrice != null ? r.fullUnitPrice * mult : undefined, lineCost: r.lineCost * mult };
    }
    const ownedLineCost = r.lineCost - shortCost;
    const lineCost = ownedLineCost * mult + shortCost * guestPriceMultiplier;
    const qty = el.qty || 0;
    const unitPrice = qty > 0 ? lineCost / qty : r.unitPrice * mult;
    return { ...r, unitPrice, fullUnitPrice: r.fullUnitPrice != null ? r.fullUnitPrice * mult : undefined, lineCost };
  }, [getElPriceRaw, guestPriceMultiplier, activeFnMeta, dealCheckData, studioFloralData]);

  // What repainting an element costs, from the same inventory list the cost sheet reads (Deal Check's once it is
  // loaded, else the IMS list) — so a zone's total, Build's Elements tile, Summary and the cost sheet's
  // "Paint:" lines all carry the same figure (paint used to be on the cost sheet only).
  const paintInv = useMemo(() => (dealCheckData?.inventory?.length ? dealCheckData.inventory : imsInventory), [dealCheckData, imsInventory]);
  const paintCtx = useMemo(() => ({ inventory: paintInv, defaultPaintCost: imsDefaultPaintCost }), [paintInv, imsDefaultPaintCost]);
  const paintFor = useCallback((el, rc) => paintTotalFor(el, { ...paintCtx, rcSub: rc?.sub }), [paintCtx]);

  const calcElsCost = useCallback((elements, withFloral, zc, opts, venueName) => {
    return (elements || []).reduce((s, el, i) => {
      // With opts.zoneKey, each row is priced by the same booking-wide shortfall allocation as
      // Build's own element cards (zoneKey + elIdx) — so zone totals and the Live Estimate add up
      // to the cards, and match the Total Estimate / cost sheet, which price the same way.
      const { rc, lineCost } = getElPrice(el, zc, opts?.zoneKey != null ? { ...opts, elIdx: i } : opts, venueName);
      const paint = paintFor(el, rc);
      if (!withFloral || !rc) return s + lineCost + paint;
      if (rc.unit === "truss_sqft") return s + applyFloralRatio(lineCost, rc) + paint;
      return s + (el.qty || 0) * applyFloralRatio(lineCost / (el.qty || 1), rc) + paint;
    }, 0);
  }, [getElPrice, applyFloralRatio, paintFor]);

  // Freezes every element's resolved rate at save time, for the active function only (the other
  // functions are stored builds with no live pricing run against them — same scoping fnTotals
  // above already accepts). Pricing has always been recomputed live against stock availability and
  // the date-category multiplier, both of which can move under an UNCHANGED build — which is
  // exactly what made the Naman Nagpal incident (2026-10-11, ₹8,63,725 → ₹6,98,714 with nothing
  // edited) take hours of SQL archaeology to explain, because no save had ever recorded what each
  // item's rate actually was. Read-only and additive: nothing here feeds back into live pricing.
  const buildElementPriceSnapshot = useCallback(() => {
    const out = {};
    const allZoneKeys = [...zoneKeys, ...(customZones || []).map((cz) => cz.id)];
    allZoneKeys.forEach((zk) => {
      const els = zoneElements[zk];
      if (!Array.isArray(els) || !els.length) return;
      const zc = zoneConfig[zk];
      out[zk] = els.map((el, i) => {
        const r = getElPrice(el, zc, { checkAvailability: true, zoneKey: zk, elIdx: i }, activeFnMeta?.venue || venue);
        return { unitPrice: r.unitPrice, lineCost: r.lineCost, fullUnitPrice: r.fullUnitPrice ?? null, warning: r.warning || null };
      });
    });
    return out;
  }, [zoneKeys, customZones, zoneElements, zoneConfig, getElPrice, venue]);

  // checkAvail (optional): mirrors getElPrice's opts.checkAvailability. blocksForDate (optional) is
  // the specific function's OWN date's blocks (from the blocksByDate map — see the warming effect
  // below) — pass it whenever checkAvail is true for a function that ISN'T necessarily the active
  // one, so its shortfall prices against its own date rather than falling back to whichever date
  // activeBlocksForDate happens to be warmed for. Omitted, it falls back to activeBlocksForDate
  // inside getElPriceFromInventory, same as before this existed.
  // venueName (optional, no default): unlike getElPrice, this variant is explicitly "for a given
  // function snapshot" — callers iterate their OWN fns/fnData with its own fnVenue, so there is no
  // single correct default the way activeFnMeta.venue is for the always-active-function getElPrice.
  // Omit it and a Repeat zone here simply prices at full rate, same as before this existed.
  // fnIdx (optional, trailing): the index of the function being priced. Passed through with fnRatio
  // so inventory/recipe pricing uses THIS function's own flower mix and own stock reservation, not
  // the active tab's — that fallback made the event total change with whichever tab was open.
  const getElPriceForFnRaw = useCallback((el, zc, fnRatio, checkAvail, venueName, blocksForDate, crossFnReusePool, fnIdx, zoneKey, elIdx, fnDate) => {
    if (isFoc(el)) return FOC_PRICE; // left at the venue from a previous event — billed nothing, guest or internal
    if (el.invId) return getElPriceFromInventory(el, { checkAvailability: !!checkAvail, zc, venueName, blocksForDate, crossFnReusePool, fnRatio, fnIdx, zoneKey, elIdx, fnDate }); // zoneKey+elIdx → the same booking-wide shortfall allocation Build's own cards use // IMS inventory-sourced element — Rate Card never consulted
    if (el.mandiId) return floralRepeatDiscount(getElPriceFromMandi(el), el, zc); // raw mandi commodity (e.g. Loose Petals), no recipe/inventory
    if (el.patternId) return floralRepeatDiscount(getElPriceFromPattern(el, fnRatio, fnIdx), el, zc); // pure flower-recipe element, no inventory item
    const rc = rcItems.find(i => i.name.toLowerCase() === (el.name || "").toLowerCase());
    if (!rc) return { rc: null, unitPrice: 0, lineCost: 0 };
    const isFloral = (rc.cat || "").toLowerCase() === "florals";
    const mode = getFloralMode(rc, rcFloralModeByKey);
    const sz = (el.size || "").toUpperCase();
    const { realRate, artRate } = resolveRcRate(rc, sz);
    let up = 0;
    if (isFloral) {
      let modeDefault;
      if (mode === "real") modeDefault = 100;
      else if (mode === "artificial") modeDefault = 0;
      else modeDefault = Math.max(0, Math.min(100, 100 - (typeof fnRatio === "number" ? fnRatio : 70)));
      const realPct = (typeof el.realPct === "number") ? Math.max(0, Math.min(100, el.realPct)) : modeDefault;
      const autoArt = floralArtUnitRate(rc, el.size);
      const effArt = (autoArt != null) ? autoArt : (artRate > 0 ? artRate : realRate); // recipe → auto-derive; else the flat artificial rate; else fall back to the real/flat rate so a flat-priced floral (e.g. an accessory on 100% artificial with no recipe/artificial rate) never shows ₹0
      up = Math.round(realPct / 100 * realRate + (100 - realPct) / 100 * effArt);
      if (rc.unit !== "truss_sqft") up += patternExtra(rc, el.size);
    } else {
      up = realRate;
    }
    if (rc.unit === "truss_sqft") {
      const d = (zc && zc.dims) || {};
      const fd = (zc && zc.floorDims) || d;
      let area = 0;
      if (zc && zc.trT === "box") area = (d.L || 0) * (d.W || 0);
      else area = (fd.L || 0) * (fd.W || 0);
      const tr = { rc, unitPrice: up, lineCost: area * up, area };
      return isFloral ? floralRepeatDiscount(tr, el, zc) : tr;
    }
    const r = { rc, unitPrice: up, lineCost: (el.qty || 0) * up };
    return isFloral ? floralRepeatDiscount(r, el, zc) : r;
  }, [rcItems, getFloralMode, rcFloralModeByKey, floralArtUnitRate, patternExtra, resolveRcRate, getElPriceFromInventory, getElPriceFromPattern, getElPriceFromMandi, hideDiscountFromClient]);
  // Same guestPriceMultiplier + dateCategoryMultiplierFor fold as getElPrice, for the export/
  // collectAllFunctionData path — fnDate (optional, new) is THIS function's own date (multi-function
  // bookings can span several dates/categories), not necessarily the active function's clientDate.
  // Omitted, it prices at 1x category multiplier same as before this existed.
  const getElPriceForFn = useCallback((el, zc, fnRatio, checkAvail, venueName, blocksForDate, fnDate, crossFnReusePool, fnIdx, zoneKey, elIdx) => {
    const r = getElPriceForFnRaw(el, zc, fnRatio, checkAvail, venueName, blocksForDate, crossFnReusePool, fnIdx, zoneKey, elIdx, fnDate);
    const mult = guestPriceMultiplier * (isFlowerPriced(el, r) ? 1 : dateCategoryMultiplierFor(fnDate));
    if (mult === 1) return r;
    // Same shortCost carve-out as getElPrice's own wrapper (its comment has the full reasoning) —
    // r.shortCost is only ever set by getElPriceFromInventory, so every other element type reduces
    // to the exact same blanket multiplication as before.
    const shortCost = Number(r.shortCost) || 0;
    if (shortCost <= 0) return { ...r, unitPrice: r.unitPrice * mult, lineCost: r.lineCost * mult };
    const ownedLineCost = r.lineCost - shortCost;
    const lineCost = ownedLineCost * mult + shortCost * guestPriceMultiplier;
    const qty = el.qty || 0;
    const unitPrice = qty > 0 ? lineCost / qty : r.unitPrice * mult;
    return { ...r, unitPrice, lineCost };
  }, [getElPriceForFnRaw, guestPriceMultiplier, dealCheckData, studioFloralData]);

  // crossFnReusePool (optional): a mutable Map<invId, remainingQty> from the matching prior
  // function (see findCrossFnReuseSource/computeFnInvQty) — passed straight through to every
  // element's pricing call so the same guest-facing cross-function reuse discount as Fixed-Venue
  // standing units applies. Omitted by every existing caller that has no such pool (full price).
  const calcElsCostForFn = useCallback((elements, zc, fnRatio, checkAvail, venueName, blocksForDate, fnDate, crossFnReusePool, fnIdx, zoneKey) => {
    return (elements || []).reduce((s, el, i) => { const r = getElPriceForFn(el, zc, fnRatio, checkAvail, venueName, blocksForDate, fnDate, crossFnReusePool, fnIdx, zoneKey, zoneKey != null ? i : undefined); return s + r.lineCost + paintFor(el, r.rc); }, 0);
  }, [getElPriceForFn, paintFor]);

  // The price badge on every UNSELECTED photo tile: what this zone would cost if you picked this
  // photo instead. Its whole job is to be compared against the selected tile's number, which comes
  // from zoneTotal — and zoneTotal prices with {checkAvailability:true}, so anything short in stock
  // for this date is charged at the shortfall rate rather than the full one.
  // Without the same flag here, the two sides of that comparison were priced by different rules:
  // every preview quoted the full rate, so a photo needing short stock advertised a number nobody
  // would ever be charged, and selecting it changed the price the moment you clicked. Same bug the
  // "By zone" row already carries a note about in StudioBuild — this was the remaining call site.
  const calcPhotoCost = useCallback((zoneKey, photo) => {
    const zc = (photo?.dims && Object.values(photo.dims).some(v => v > 0)) ? buildZoneConfig(zoneKey, photo.dims) : null;
    const elCost = calcElsCost(photo?.elements, true, zc, { checkAvailability: true });
    const structCost = zc ? scaleStruct(calcStructCost(zoneKey, zc, structRates, structDiscountFor(zc, activeFnMeta?.venue || venue))).total : 0;
    return elCost + structCost;
  }, [calcElsCost, structRates, guestPriceMultiplier, venue, hideDiscountFromClient, fvCfgForRepeat]);

  const calcFullEventCost = useCallback((ev) => {
    if (!ev) return 0;
    let decorCost = 0;
    let totalFloralCostFull = 0;
    const itemAgg = {};
    const vidUrl = ev.video || "";
    const vidMatch = vidUrl.match(/embed\/([a-zA-Z0-9_-]{11})/);
    const vidId = vidMatch ? vidMatch[1] : null;
    const vTag = vidId ? (ytVideoTags[vidId] || {}) : {};
    const zonePhotos = vTag.zonePhotos || {};
    Object.entries(zonePhotos).forEach(([zk, libId]) => {
      const li = libItems.find(l => l.id === libId);
      if (!li) return;
      const pd = li.dims || {};
      if (pd.trussW || pd.trussL || pd.trussH || pd.floorL || pd.floorW) {
        const zc = buildZoneConfig(zk, pd);
        if (zc) decorCost += calcStructCost(zk, zc, structRates).total;
        const tL = pd.trussL || 0, tW = pd.trussW || 0;
        const tSqft = tL * tW;
        if (tSqft > 0) { const tc = truckCap.find(t => t.item.toLowerCase().includes("truss") && t.perTruck > 0); if (tc) itemAgg[tc.id] = (itemAgg[tc.id] || 0) + tSqft; }
        const fL = pd.floorL || tL, fW = pd.floorW || tW;
        const fSqft = fL * fW;
        if (fSqft > 0) {
          const ptc = truckCap.find(t => t.item.toLowerCase().includes("platform") && t.perTruck > 0);
          if (ptc && pd.plH) itemAgg[ptc.id] = (itemAgg[ptc.id] || 0) + fSqft;
          const ctc = truckCap.find(t => t.item.toLowerCase().includes("carpet") && t.perTruck > 0);
          if (ctc) itemAgg[ctc.id] = (itemAgg[ctc.id] || 0) + fSqft;
        }
      }
      if (!(li.elements || []).length) return;
      (li.elements || []).forEach(el => {
        if (el.invId) { decorCost += getElPriceFromInventory(el).lineCost; return; } // IMS inventory-sourced — no Rate Card lookup
        if (el.patternId) { decorCost += getElPriceFromPattern(el).lineCost; return; } // pure flower-recipe element, no inventory item
        const rc = rcItems.find(i => i.name.toLowerCase() === (el.name || "").toLowerCase());
        if (!rc) return;
        const sz = (el.size || "").toUpperCase();
        let up = resolveRcRate(rc, sz).realRate;
        if ((rc.cat || "").toLowerCase() === "florals") {
          totalFloralCostFull += (el.qty || 0) * up;
          up = getElPrice(el, null).unitPrice;
        } else {
          const subTc = truckCap.find(tc => (Number(tc.perTruck) || 0) > 0 && String(tc.item || "").toLowerCase().trim() === String(rc.sub || "").toLowerCase().trim());
          if (subTc) itemAgg[subTc.id] = (itemAgg[subTc.id] || 0) + (el.qty || 0);
        }
        decorCost += (el.qty || 0) * up;
      });
    });
    const venueName = ev.venue || "";
    const match = resolveTrVenue(trVenues, venueName, venueParents);
    const tripRate = match ? match.rate : 0;
    let truckFrac = 0;
    Object.entries(itemAgg).forEach(([tcId, qty]) => { const tc = truckCap.find(t => t.id === tcId); if (!tc || !tc.perTruck) return; truckFrac += qty / tc.perTruck; });
    const itemTrucks = Math.ceil(truckFrac);
    const floralTrucks = 0; // florals counted via their sub-category capacity — no separate flower truck
    const bt = bufferTiers.find(b => decorCost >= b.minBudget && decorCost < b.maxBudget);
    const bufTrucks = bt ? bt.bufferTrucks : 0;
    // No decor priced at all → nothing to deliver or power, so skip truck/genset cost entirely
    // (matches calcFunctionCost/calcFunctionBreakdown, which already gate transport on decor > 0).
    if (decorCost <= 0) return decorCost;
    const allTrucks = itemTrucks + floralTrucks + bufTrucks;
    const truckTotal = allTrucks * tripRate * 2;
    // 125 KVA count follows the venue only (no customGensets here, matching this function's prior
    // behaviour — this is a Browse-card estimate, not the live deal's own priced total).
    const gensetCost = resolveGensetPlan(match, null, genset62, gensetRate, gensetRate62).gensetCost;
    return decorCost + truckTotal + gensetCost;
  }, [ytVideoTags, libItems, rcItems, getElPrice, resolveRcRate, getElPriceFromInventory, getElPriceFromPattern, trVenues, truckCap, floralPerTruck, bufferTiers, gensetRate, gensetRate62, genset62, structRates, venueParents]);

  const fullCostMap = useMemo(() => {
    const m = {};
    events.forEach(ev => { m[ev.id] = calcFullEventCost(ev); });
    return m;
  }, [events, calcFullEventCost]);
  const getFullCost = useCallback((ev) => fullCostMap[ev.id] ?? calcFullEventCost(ev), [fullCostMap, calcFullEventCost]);

  const isPremiaPlatinum = useCallback((ev) => {
    if (!ev) return false;
    const vidUrl = ev.video || "";
    const vidMatch = vidUrl.match(/embed\/([a-zA-Z0-9_-]{11})/);
    const vidId = vidMatch ? vidMatch[1] : null;
    const tagTier = vidId ? ytVideoTags[vidId]?.tier : null;
    // Gate on TAGGING only — a design is Platinum (Sr. Designer only) purely because it's tagged
    // Platinum. Price is never used to gate, so a pricey Gold video customizes normally.
    return tagTier === "Platinum";
  }, [ytVideoTags]);

  const filteredEvents = useMemo(() => events.filter(ev => {
    if (filterCat.length > 0 && !filterCat.includes(getCat(getFullCost(ev)).label)) return false;
    if (filterFn.length > 0 && !filterFn.includes(ev.fn)) return false;
    if (filterSpace.length > 0 && !filterSpace.includes(ev.space)) return false;
    if (filterVenue !== "All" && ev.venue !== filterVenue) return false;
    return true;
  }), [events, filterCat, filterFn, filterSpace, filterVenue, getFullCost]);

  const totalCost = useCallback(() => {
    let c = 0;
    // Always derive zones fresh from the live zoneConfig/enabledEls — matches calcFunctionCost and
    // calcFunctionBreakdown below. `activeZones` used to take priority here when non-empty, but it's
    // stale legacy state (only ever repopulated from an old restored session, reset to [] on almost
    // every edit) — letting it override the live config silently priced a deal from an out-of-date
    // zone list whenever a session happened to still be carrying one.
    const zones = Object.entries(zoneConfig).filter(([zk, cfg]) => enabledEls[zk] && cfg).map(([zk, cfg]) => ({ id: zk, type: zk, name: zk, config: cfg }));
    // structDiscountFor is per-zone (zc.repeat varies per zone), unlike the old venue-only truss
    // discount this replaced.
    zones.forEach(z => { c += withPrintFlat(scaleStruct(calcStructCost(z.type, z.config, structRates, structDiscountFor(z.config, activeFnMeta?.venue || venue))), z.type, zoneConfig, enabledEls, (zk2) => !!structDiscountFor(zoneConfig[zk2], activeFnMeta?.venue || venue).print).total; }); // the ACTIVE function's venue, not function 1's
    // Cross-function reuse (guest-facing) — same eligibility activeCrossFnReuseQty already computes
    // for StudioBuild.jsx's own per-card display (see its own declaration comment for the full
    // history): this total used to have NO mechanism for it at all, so a function with a same-venue,
    // within-24h predecessor showed full undiscounted price here even while its own per-card display
    // (already threaded through) showed the correct discounted figure — the headline Live Estimate
    // disagreeing with its own cards, and with Summary/eventGrandTotal/the cost sheet, all of which
    // already netted this out. A fresh Map per call, same reasoning activeCrossFnReuseQty's own
    // comment gives for not sharing one mutable instance across callers.
    const crossFnReusePool = activeCrossFnReuseQtyRef.current ? new Map(Object.entries(activeCrossFnReuseQtyRef.current)) : null;
    Object.entries(zoneElements).forEach(([zk, elems]) => {
      if (!enabledEls[zk] || !elems) return;
      c += calcElsCost(elems, true, zoneConfig[zk], { checkAvailability: true, crossFnReusePool, zoneKey: zk }); // active fn's live canvas — see activeBlocksForDate
    });
    const fnIdx = activeFnIdx || 0;
    // Only count a custom Production/Buying item while its own zone is still enabled — matches
    // how normal element-card costs are gated by enabledEls above, and matches
    // calcFunctionBreakdown (Summary's accordion), which already scoped this way. Previously this
    // counted every custom item for the function regardless of zone toggle state, so switching a
    // zone off didn't remove its custom items from the total the way it removes everything else.
    dcCustomItems.filter(ci => ci.fnIdx === fnIdx && enabledEls[ci.zoneKey]).forEach(ci => {
      c += (ci.manualPrice || ci.refPrice || 0) * (Number(ci.qty) || 1);
    });
    return c;
  }, [venue, enabledEls, zoneConfig, zoneElements, calcElsCost, dcCustomItems, activeFnIdx, structRates, dealCheckData, studioFloralData, fvCfgForRepeat, clientLedger, activeClientId]);

  const transportCalc = useMemo(() => {
    // The ACTIVE function's own venue and date. `venue` / `clientDate` are function 1's — using them
    // here priced every function's trucks at function 1's venue rate and its floral sourcing at
    // function 1's date, so Build's Live Estimate could disagree with Summary / the cost sheet /
    // the Total Estimate (which all read each function's own venue and date) on multi-venue or
    // multi-date bookings.
    const aVenue = activeFnMeta?.venue || venue;
    const aDate = activeFnMeta?.date || clientDate;
    if (!aVenue) return { trucks: 0, tripRate: 0, total: 0, isNew: true, tier: "new", tierLabel: "", breakdown: [], floralTrucks: 0, bufferTrucks: 0, itemTrucks: 0 };
    const match = resolveTrVenue(trVenues, aVenue, venueParents);
    const isNew = !match;
    const tripRate = match ? match.rate : customTripRate;
    const tierId = match ? match.tier : "new";
    const tierLabel = match ? (TR_TIERS.find(t => t.id === match.tier)?.label || match.tier) : "New venue";
    const decor = totalCost();
    // No decor selected at all → nothing to deliver or power, so no trucks/genset either. Matches
    // calcFunctionCost/calcFunctionBreakdown, which already skip transport entirely when a
    // function's decor total is 0 — this was the one place still charging it unconditionally
    // as soon as a venue was picked, even with every zone toggled off.
    if (decor <= 0) {
      const venueOnly = resolveVenueGensets(match);
      return { trucks: 0, tripRate, total: 0, isNew, tier: tierId, tierLabel, breakdown: [], floralTrucks: 0, bufferTrucks: 0, itemTrucks: 0, totalFloralCost: 0, gensets: 0, venueGensets: venueOnly.genset125, venueGenset62: venueOnly.genset62, gensetCost: 0, gensetRate, gensetRate62, genset62: 0, truckTotal: 0 };
    }
    const breakdown = [];
    const trussInvHere = sharedFloralSettings.trussInv;
    // Real-flower kg (summed across every mandi item regardless of its own unit — an approximation,
    // see computeTruckItems' comment) + artificial bunches, for the Real Flowers / Artificial Flowers
    // truck-capacity rows. Goes through the ref, not a direct call — see calcFnFloralSourcingCostRef's
    // declaration for why (this memo is declared before calcFnFloralSourcingCost in the file).
    const floralSourcingHere = calcFnFloralSourcingCostRef.current?.({ zoneElements, enabledEls, floralOverrides, fnIdx: activeFnIdx, fnDate: aDate, floralRatio });
    const flowerMaterialQty = {
      realKg: (floralSourcingHere?.breakdown || []).reduce((s, f) => s + (f.qty || 0), 0),
      artBunches: (floralSourcingHere?.artFlowerBunches || 0) + (floralSourcingHere?.artGreenBunches || 0),
    };
    // Cross-function reuse pool for the ACTIVE function — the same source calcFunctionCost /
    // calcFunctionBreakdown use, so a function that reuses the previous function's setup (e.g. a
    // Reception straight after the Wedding) is not charged a truck for those units here while
    // Summary and the cost sheet correctly are not. Read through the ref: collectAllFunctionData
    // is declared further down (TDZ). The active function's own build is taken from live state.
    const allFnsNow = collectAllFunctionDataRef.current?.() || [];
    const activeFnData = { ...(allFnsNow.find(f => f.fnIdx === activeFnIdx) || {}), fnIdx: activeFnIdx, fnDate: aDate, fnVenue: aVenue, zoneElements, zoneConfig, enabledEls };
    const crossFnPrev = (!isFillerDateFor(aDate) && allFnsNow.length > 1) ? findCrossFnReuseSource(activeFnData, allFnsNow) : null;
    const reusePool = crossFnPrev ? new Map(Object.entries(computeFnInvQty(crossFnPrev))) : null;
    const { itemTrucks, breakdown: itemBd } = computeTruckItems(zoneElements, zoneConfig, enabledEls, rcItems, truckCap, imsInventory, sharedFloralSettings.flowerPatterns, trussInvHere, flowerMaterialQty, fvCfgForRepeat, aVenue, !hideDiscountFromClient, reusePool, structRates.printMaterials);
    itemBd.forEach(b => breakdown.push(b));
    const floralTrucks = 0, totalFloralCost = 0; // florals now counted via their sub-category capacity — no separate flower truck
    const bt = bufferTiers.find(b => decor >= b.minBudget && decor < b.maxBudget);
    const bufTrucks = bt ? bt.bufferTrucks : 0;
    if (bufTrucks > 0) breakdown.push({ label: "Buffer", qty: 0, perTruck: 0, unit: "", trucks: bufTrucks, isBuffer: true, tierLabel: bt?.label || "" });
    const allTrucks = itemTrucks + floralTrucks + bufTrucks;
    const plan = resolveGensetPlan(match, customGensets, genset62, gensetRate, gensetRate62);
    // Guest-facing markup on the venue's own trip cost (trVenues[].clientScale, Admin → Settings →
    // Transport & Power) — this calc is Build's own client-facing figure (feeds grandTotal, the
    // Live Estimate rail and the Build page total panel — nothing internal reads transportCalc),
    // so unlike calcFunctionBreakdown there's no separate raw field to keep: truckTotal/total ARE
    // the client price here. Scoped to the truck/trip line only, not genset. Defaults to 1.25
    // (25% markup, the owner's requested starting point) for a venue nobody has set it on.
    const rawTruckTotal = allTrucks * tripRate * 2;
    const clientScale = Number(match?.clientScale) > 0 ? Number(match.clientScale) : 1.25;
    const truckTotal = rawTruckTotal * clientScale * guestPriceMultiplier;
    // gensetCost is already the GUEST-billed figure (resolveGensetPlan's own gensetCostOurs is the
    // separate, unscaled figure Deal Check's Power tab reads for what we actually pay the vendor).
    const gensetCostForGuest = plan.gensetCost * guestPriceMultiplier;
    const total = truckTotal + gensetCostForGuest;
    return { trucks: allTrucks, tripRate, total, isNew, tier: tierId, tierLabel, breakdown, floralTrucks, bufferTrucks: bufTrucks, itemTrucks, totalFloralCost, gensets: plan.genset125, venueGensets: plan.venueGenset125, venueGenset62: plan.venueGenset62, gensetCost: gensetCostForGuest, gensetRate, gensetRate62, genset62: plan.genset62, truckTotal, clientScale };
  }, [structRates, venue, customTripRate, customGensets, gensetRate, gensetRate62, genset62, trVenues, zoneElements, enabledEls, rcItems, truckCap, floralPerTruck, bufferTiers, totalCost, zoneConfig, imsInventory, dealCheckData, studioFloralData, floralOverrides, floralRatio, activeFnIdx, clientDate, fvCfgForRepeat, venueParents, clientLedger, activeClientId, activeFnMeta, fnBuilds, extraFunctions, hideDiscountFromClient]);

  // agencyFeeAmt is split out of grandTotal (not just an inline Math.round(grandTotal*pct/(100+pct)))
  // so Build's own Live Estimate rail can show the fee as its own visible line — same "its own line,
  // not folded silently into any total" convention the Cost Sheet's Agency Fee row already uses.
  // Without it, Décor + Transport (+ By-zone) never added back up to the headline number, which read
  // exactly like the fee had been dropped even though grandTotal already carried it.
  const agencyFeeAmt = useMemo(() => {
    const base = totalCost() + transportCalc.total;
    const fvCfg = { fixedVenues: sharedFloralSettings.fixedVenues, venueParents: venueParents || dealCheckData?.venueParents || {} };
    const discounted = Math.max(0, base - fixedVenueDealDiscount(fvCfg, [{ fnVenue: activeFnMeta?.venue || venue }], () => base, base)); // the ACTIVE function's venue — see transportCalc
    const feePct = sharedFloralSettings.agencyFeePct;
    return Math.round(discounted * feePct / 100);
  }, [totalCost, transportCalc, dealCheckData, venue, activeFnMeta, studioFloralData, sharedFloralSettings, venueParents]);

  const grandTotal = useMemo(() => {
    const base = totalCost() + transportCalc.total;
    // Fixed-venue discount — same as eventGrandTotal's, just for this one active function/venue.
    // Same studioFloralData/venueParents fallback as eventGrandTotal, for the same reason.
    const fvCfg = { fixedVenues: sharedFloralSettings.fixedVenues, venueParents: venueParents || dealCheckData?.venueParents || {} };
    const discounted = Math.max(0, base - fixedVenueDealDiscount(fvCfg, [{ fnVenue: activeFnMeta?.venue || venue }], () => base, base)); // the ACTIVE function's venue — see transportCalc
    // Agency fee (Admin → Settings, default 25%) — this is Build's own live "page total" for the
    // active function, the number a salesperson watches while building. It has to carry the fee too,
    // or it would visibly disagree with eventGrandTotal/Deal Check/the cost sheet, which all do.
    return discounted + agencyFeeAmt;
  }, [totalCost, transportCalc, dealCheckData, venue, activeFnMeta, studioFloralData, sharedFloralSettings, venueParents, agencyFeeAmt]);

  // What was actually saved for THIS function, last time — so Build's Live Estimate can flag when
  // the live figure above has drifted from it. Same precedence Browse's own session-card price
  // already uses (the row's own column > fnTotals > the session-level total, only if it's tagged
  // as belonging to this function or isn't tagged at all) — one definition of "the last saved
  // price for this function", not a second copy that could disagree with Browse's.
  // Confirmed incident this was built for: an UNEDITED build swung ~₹1.1L in a few hours from
  // shared-inventory contention plus the LMS date-category auto-sync (buildDateCategories,
  // lib/ims/lms.js) re-firing — nothing a salesperson did, and nothing on screen said so.
  const lastSavedFnTotal = useMemo(() => {
    const cli = clientLedger.find((c) => c.id === activeClientId);
    const top = cli?.sessions?.[0];
    if (!top) return null;
    const row = Array.isArray(top._fnRows) ? top._fnRows.find((r) => r && r.fn_idx === activeFnIdx) : null;
    if (row && row.total != null && Number(row.total) > 0) return { total: Number(row.total), tier: row.tier || "" };
    const own = top.fnTotals && (top.fnTotals[activeFnIdx] || top.fnTotals[String(activeFnIdx)]);
    if (own && typeof own.total === "number" && own.total > 0) return own;
    const tagged = typeof top.savedActiveFnIdx === "number";
    if (tagged && top.savedActiveFnIdx !== activeFnIdx) return null;
    if (typeof top.total === "number" && top.total > 0) return { total: top.total, tier: top.tier };
    return null;
  }, [clientLedger, activeClientId, activeFnIdx]);

  // ── EVERY FUNCTION OF THE OPEN DEAL HAS LOADED ── (owner ask 2026-11-13) Browse's saved-build "Continue / Resume build"
  // stays disabled until this is true: the ledger and the deal restore are in, pricing is ready, no function switch is in
  // flight, and every function the latest saved session holds a build for is in memory (fnBuilds, or the one on screen).
  // Continuing earlier could land on a Build whose other functions were not there yet.
  const allFnsLoaded = useMemo(() => {
    if (!ledgerReady || restoring || !pricingReady || isFnSwitching) return false;
    if (!activeClientId) return true;
    const cli = clientLedger.find((c) => c.id === activeClientId);
    const totalFns = 1 + (extraFunctions || []).length;
    // Every function the deal has (its saved row) must be on screen - the Function chips are drawn from these. A function added in
    // Event Info reached Browse a moment after the button had already turned on (owner's recording 2026-11-13).
    if (Array.isArray(cli?.functions) && cli.functions.length > totalFns) return false;
    const top = cli?.sessions?.[0];
    if (!top) return true;
    const withData = new Set();
    if (Array.isArray(top._fnRows)) top._fnRows.forEach((r) => { if (r && r.has_data && Number.isInteger(Number(r.fn_idx))) withData.add(Number(r.fn_idx)); });
    else Object.keys(top.fnSnapshots || {}).forEach((k) => withData.add(Number(k)));
    for (const i of withData) {
      if (i === activeFnIdx || i < 0) continue;
      // a saved build for a function not on screen yet is still loading (Browse's 10s backstop covers one that was removed)
      if (i >= totalFns || !fnBuilds || fnBuilds[i] == null) return false;
    }
    return true;
  }, [ledgerReady, restoring, pricingReady, isFnSwitching, activeClientId, clientLedger, extraFunctions, activeFnIdx, fnBuilds]);

  // Every function's data, built once per change of its inputs: dozens of calls per render (every price, floral and stock
  // check) used to each build the whole list afresh. Callers only read it - the same objects are handed to each.
  const allFunctionData = useMemo(() => {
    const all = [];
    const totalFns = 1 + (extraFunctions || []).length;
    for (let idx = 0; idx < totalFns; idx++) {
      const meta = idx === 0
        ? { type: fn || "", date: clientDate || "", venue: venue || "", shift: clientShift || "", pax: clientPax || "", palette: clientPalette || "Custom", flowerPalette: clientFlowerPalette || "" }
        : (() => { const ef = extraFunctions[idx - 1] || {}; return { type: ef.type || "", date: ef.date || "", venue: ef.venue || "", shift: ef.shift || "", pax: ef.pax || "", palette: ef.palette || "Custom", flowerPalette: ef.flowerPalette || "" }; })();
      const isActive = idx === activeFnIdx;
      const snap = isActive
        ? { zoneElements, zoneConfig, enabledEls, elSelectedPhoto, itemQty, itemGrades, activeZones, zoneOrder, customZones, elTiers, floralRatio, genset62, customGensets, customTripRate, elNotes, floralOverrides, sourceVideo }
        : (fnBuilds[idx] || {});
      all.push({
        fnIdx: idx,
        fnType: meta.type,
        fnDate: meta.date,
        fnVenue: meta.venue,
        fnShift: meta.shift,
        fnPax: meta.pax,
        fnPalette: meta.palette,
        fnFlowerPalette: meta.flowerPalette,
        zoneElements: snap.zoneElements || {},
        zoneConfig: snap.zoneConfig || {},
        enabledEls: snap.enabledEls || {},
        elSelectedPhoto: snap.elSelectedPhoto || {},
        itemQty: snap.itemQty || {},
        itemGrades: snap.itemGrades || {},
        activeZones: snap.activeZones || [],
        zoneOrder: snap.zoneOrder || [],
        customZones: snap.customZones || [],
        elTiers: snap.elTiers || {},
        floralRatio: typeof snap.floralRatio === "number" ? snap.floralRatio : floralRatio,
        customGensets: typeof snap.customGensets === "number" ? snap.customGensets : null,
        genset62: typeof snap.genset62 === "number" ? snap.genset62 : null,
        customTripRate: typeof snap.customTripRate === "number" ? snap.customTripRate : 0,
        elNotes: snap.elNotes || {},
        floralOverrides: snap.floralOverrides && typeof snap.floralOverrides === "object"
          ? { note: snap.floralOverrides.note || "", rows: Array.isArray(snap.floralOverrides.rows) ? snap.floralOverrides.rows : [] }
          : { note: "", rows: [] },
        // Read-only, for the early-warning check below (duplicateSourceVideoFnIdxs) — never part of
        // any write-refusal guard, so it does not need the stricter care suspiciousDuplicateFnIdxs'
        // own inputs get.
        sourceVideo: snap.sourceVideo || null,
      });
    }
    return all;
  }, [fn, clientDate, venue, clientShift, clientPax, clientPalette, clientFlowerPalette, zoneElements, zoneConfig, enabledEls, elSelectedPhoto, itemQty, itemGrades, activeZones, zoneOrder, customZones, elTiers, floralRatio, customGensets, customTripRate, elNotes, floralOverrides, extraFunctions, fnBuilds, activeFnIdx, sourceVideo]);
  const collectAllFunctionData = useCallback(() => allFunctionData, [allFunctionData]);
  // Layout, same reasoning as snapshotFnRef / saveSessionRef — read from synchronous paths.
  useLayoutEffect(() => { collectAllFunctionDataRef.current = collectAllFunctionData; });
  // ── EARLY WARNING: TWO FUNCTIONS JUST STARTED SHARING ONE REFERENCE VIDEO ──
  // duplicateSourceVideoFnIdxs' own comment has the full story — this is a one-time, non-blocking
  // heads-up (never refuses a save, unlike suspiciousDuplicateFnIdxs) meant to catch the Sahiba-
  // class symptom (a function silently taking on a SIBLING's content) within seconds instead of
  // the ~week it actually took to notice (2026-11-13). warnedVideoPairsRef survives re-renders but
  // is cleared on every loadClientSession (see its own reset there) so a brand-new client/deal
  // doesn't inherit a previous client's already-dismissed pairs, or suppress a genuinely new one.
  useEffect(() => {
    duplicateSourceVideoFnIdxs(allFunctionData).forEach(([a, b]) => {
      const vid = allFunctionData.find((fd) => fd.fnIdx === a)?.sourceVideo?.id || "";
      const key = `${a}:${b}:${vid}`;
      if (warnedVideoPairsRef.current.has(key)) return;
      warnedVideoPairsRef.current.add(key);
      console.warn(`[duplicateSourceVideoFnIdxs] Function ${a + 1} and Function ${b + 1} now share the same reference video — if this wasn't deliberate, check both builds.`);
      showMsg?.(`Heads up: Function ${a + 1} and Function ${b + 1} now have the same reference video. If that wasn't on purpose, check both builds.`, "red");
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [allFunctionData]);

  // Pre-Sold gate (owner ask, 2026-10-17): "ensure we have no deals that go out with out-of-stock
  // stuff" — walks every function/zone/element of the WHOLE build (not just the active tab) the
  // exact same way calcFunctionCost already does for its own total (same fBlocksForDate-per-fnDate,
  // same cross-function reuse pool), but keeps every element's own getElPriceForFn result instead of
  // summing it, so it can report which ones came back outOfStock (StudioApp.jsx's
  // getElPriceFromInventory — short AND canFulfillShortfall false, lib/rateCard.js). Only plain
  // invId elements are checked — a kit/pattern/mandi element never sets outOfStock at all; a kit is checked through its
  // parts instead (kitPartShorts).
  const scanOutOfStockElements = useCallback(() => {
    const allFns = collectAllFunctionData();
    const flagged = [];
    allFns.forEach((fnData) => {
      const fZoneElements = fnData.zoneElements || {};
      const fEnabledEls = fnData.enabledEls || {};
      const fZoneConfig = fnData.zoneConfig || {};
      const fFloralRatio = typeof fnData.floralRatio === "number" ? fnData.floralRatio : 70;
      const fBlocksForDate = blocksByDate[fnData.fnDate];
      // Whether stock is THERE, not what it costs: pieces already standing at the venue from the deal's own same-day / previous-day
      // function count, whatever the guest-discount toggle or a Filler date say (those only decide the price). The discount gate cut
      // this credit too, so a sofa used in Haldi and again in Sangeet the same day read out of stock at Sold (RC-11).
      const crossFnPrevFn = findCrossFnReuseSource(fnData, allFns);
      const reusePool = crossFnPrevFn ? new Map(Object.entries(computeFnInvQty(crossFnPrevFn))) : null;
      // the same function's pieces, kit parts included, for the kit-part check
      const partReusePool = crossFnPrevFn ? fnUnitQty(crossFnPrevFn, imsInventory) : null;
      Object.entries(fZoneElements).forEach(([zk, elems]) => {
        if (!fEnabledEls[zk] || !Array.isArray(elems)) return;
        elems.forEach((el, i) => {
          if (!el?.invId || !(Number(el.qty) || 0) > 0) return;
          const r = getElPriceForFn(el, fZoneConfig[zk], fFloralRatio, true, fnData.fnVenue, fBlocksForDate, fnData.fnDate, reusePool, fnData.fnIdx, zk, i);
          // A kit is also stopped by a part inside it that is short and can't be made (kitPartShorts).
          const partsOut = kitPartShorts(el, { fnIdx: fnData.fnIdx, zoneKey: zk, elIdx: i, fnDate: fnData.fnDate, venueName: fnData.fnVenue, blocksForDate: fBlocksForDate, reusePool: partReusePool })
            .filter((p) => !p.canMake);
          if (r.outOfStock || partsOut.length) {
            const item = (imsInventory || []).find((x) => x.id === el.invId);
            // idx/invId carried so the gate modal's own 📦 picker can open directly against this
            // exact element (openAvailModal(zoneKey, idx, el, rc)) instead of only pointing the
            // salesperson at the right function/zone and making them find it by hand.
            flagged.push({ fnIdx: fnData.fnIdx, fnLabel: fnData.fnType || `Function ${fnData.fnIdx + 1}`, fnDate: fnData.fnDate || "", zoneKey: zk, idx: i, invId: el.invId, name: item?.name || el.name || "Item",
              parts: partsOut.map((p) => `${p.name} (${p.short} short)`),
              // the gate lists each short part as its own row, and its Fix opens the picker on that part, not the kit
              itemOut: !!r.outOfStock, shortParts: partsOut.map((p) => ({ id: p.id, name: p.name })),
              // what is short, by name only - the gate modal shows just this: the item itself when it is out, and/or the kit part(s) that are
              shortNames: [...new Set([...(r.outOfStock ? [item?.name || el.name || "Item"] : []), ...partsOut.map((p) => p.name)])] });
          }
        });
      });
    });
    return flagged;
  }, [collectAllFunctionData, blocksByDate, getElPriceForFn, imsInventory, kitPartShorts]);

  // Pre-Sold gate #2 — same "physically can't be delivered" reasoning as scanOutOfStockElements
  // above, for truss pillars/beams, platform sqft, and batta RFT instead of a tagged inventory item.
  // Computes exactly what THIS build would draw from each date's real stock pool (same functions
  // IMS's own promote-on-sold effect uses — buildEventAllocation/buildEventPlatformAllocation/
  // buildEventBattaAllocation), folds it onto that date's CURRENT real pool (studioFloralData.
  // trussAlloc/platformAlloc/battaAlloc, minus this same client's own existing reservation so
  // re-confirming an already-booked deal doesn't double-count itself), and runs the identical
  // allocateForDate/allocatePlatformForDate/allocateBattaForDate hard/soft priority check IMS uses.
  // A sentinel eoId ("__self_check__") identifies this hypothetical entry in the result — hard
  // events are processed oldest-first and this one is always newest, so if the date's stock can't
  // cover everything, THIS entry is the one that ends up bearing shortageBorne (unless some
  // ALREADY-sold event was already over-committed before this build existed, which isn't this
  // salesperson's problem to fix and correctly stays unflagged).
  const SELF_CHECK_EOID = "__self_check__";
  const scanTrussStockShortage = useCallback(() => {
    const trussInv = studioFloralData?.trussInv;
    if (!trussInv) return [];
    const allFns = collectAllFunctionData();
    const byDate = {};
    allFns.forEach((fnData) => {
      if (!fnData.fnDate) return;
      (byDate[fnData.fnDate] ||= []).push({ fnIdx: fnData.fnIdx, date: fnData.fnDate, zones: fnData.zoneConfig || {}, enabledEls: fnData.enabledEls || {} });
    });
    const flagged = [];
    Object.entries(byDate).forEach(([date, fnsForDate]) => {
      const meta = { eoId: SELF_CHECK_EOID, clientId: activeClientId || "self", clientName: clientName?.trim() || "This build", state: "hard", createdAt: Date.now() };
      const excludeMine = (ev) => ev.eoId !== SELF_CHECK_EOID && ev.clientId !== activeClientId;

      const trussEntry = buildEventAllocation(meta, fnsForDate, trussInv);
      if (trussEntry.trusses?.length) {
        const list = [...(studioFloralData.trussAlloc?.[date]?.events || []).filter(excludeMine), trussEntry];
        const result = allocateForDate({}, date, list, trussInv, "studio-presale-check");
        if (list.find((ev) => ev.eoId === SELF_CHECK_EOID)?.shortageBorne) {
          const sm = result[date]?.stockSummary;
          // overflowPillars/overflowBeams are keyed "<material>|<size>" (trussEngine.js's
          // computePoolFeasibility, 2026-11-14 — material-aware stock, see its own header comment) —
          // "iron" is left off the label since it's the common/default case, any other material is
          // named so the salesperson knows which skeleton is actually short.
          const label = (k, unit) => { const [mat, sz] = k.split("|"); return `${sz}ft ${unit}${mat !== "iron" ? ` (${mat})` : ""}`; };
          const bits = [...Object.entries(sm?.overflowPillars || {}).map(([k, q]) => `${q}× ${label(k, "pillar")}`), ...Object.entries(sm?.overflowBeams || {}).map(([k, q]) => `${q}× ${label(k, "beam")}`)];
          flagged.push({ domain: "truss", emoji: "🏗️", date, detail: bits.join(", ") || "stock shortfall" });
        }
      }

      const platEntry = buildEventPlatformAllocation(meta, fnsForDate);
      if (Object.keys(platEntry.totalPlatformSqftByMaterial).length) {
        const list = [...(studioFloralData.platformAlloc?.[date]?.events || []).filter(excludeMine), platEntry];
        const result = allocatePlatformForDate({}, date, list, trussInv, "studio-presale-check");
        if (list.find((ev) => ev.eoId === SELF_CHECK_EOID)?.shortageBorne) {
          const over = result[date]?.stockSummary?.overflow || {};
          flagged.push({ domain: "platform", emoji: "🛏️", date, detail: Object.values(over).map((sqft) => `${sqft} sqft`).join(", ") || "stock shortfall" });
        }
      }

      const battaEntry = buildEventBattaAllocation(meta, fnsForDate, trussInv);
      if (Object.keys(battaEntry.totalBattaRftByMaterial).length) {
        const list = [...(studioFloralData.battaAlloc?.[date]?.events || []).filter(excludeMine), battaEntry];
        const result = allocateBattaForDate({}, date, list, trussInv, "studio-presale-check");
        if (list.find((ev) => ev.eoId === SELF_CHECK_EOID)?.shortageBorne) {
          const over = result[date]?.stockSummary?.overflow || {};
          flagged.push({ domain: "batta", emoji: "🧵", date, detail: Object.entries(over).map(([m, rft]) => `${rft} RFT ${m}`).join(", ") || "stock shortfall" });
        }
      }
    });
    return flagged;
  }, [studioFloralData, collectAllFunctionData, activeClientId, clientName]);

  // The SAME cross-function reuse quantities calcFunctionCost/calcFunctionBreakdown already build
  // and fold into the Live Estimate/Summary/Deal Check totals for the active function — but Build's
  // own LIVE per-card view (getElPrice/calcElsCost, called directly by StudioBuild.jsx, never
  // threaded through venueName/crossFnReusePool at all) never received it. Result: an item that
  // plainly qualifies (same deal, same venue, within 24h of the prior function) still showed full,
  // undiscounted price on its own card even with the guest-discount toggle on, while the aggregate
  // total elsewhere had already netted the very same discount out of its sum — the card and the
  // total it's part of silently disagreed. Exposed via ctx so StudioBuild.jsx can thread this into
  // its own calcElsCost/getElPrice calls too, same eligibility, same gating.
  //
  // A plain qty-by-invId OBJECT, not a ready-made Map — getElPriceFromInventory's crossFnReusePool
  // is a MUTABLE Map it draws down as each element claims its share (so a second element on the same
  // invId can't double-claim it), and calcFunctionCost/calcFunctionBreakdown deliberately build a
  // FRESH Map on every invocation for exactly that reason. Memoizing a single shared Map here would
  // have every call site draw down the SAME instance across one render (sectionCost, elCardSummary,
  // zoneTotal, and every per-card getElPrice all price the same elements), silently exhausting the
  // reuse quantity after the first caller and starving the rest. Each StudioBuild.jsx call site
  // builds its own `new Map(Object.entries(activeCrossFnReuseQty))` right before using it instead.
  const activeCrossFnReuseQty = useMemo(() => {
    const all = collectAllFunctionData();
    const fnData = all[activeFnIdx];
    if (!fnData || isFillerDateFor(fnData.fnDate)) return null;
    const prevFn = findCrossFnReuseSource(fnData, all);
    return prevFn ? computeFnInvQty(prevFn) : null;
  }, [collectAllFunctionData, activeFnIdx, dealCheckData, studioFloralData]);
  // Layout, same TDZ reasoning as collectAllFunctionDataRef — totalCost (declared above this) reads
  // the ref instead of the memo directly.
  useLayoutEffect(() => { activeCrossFnReuseQtyRef.current = activeCrossFnReuseQty; });
  // invId → sibling function names (same venue, same/next day) that also use that item — drives the
  // orange rate on Build's element cards. Deliberately NOT gated by hideDiscountFromClient or the Filler
  // date rule: it is a heads-up for the salesperson, not a price change.
  const activeSiblingFnInvUse = useMemo(() => {
    const all = collectAllFunctionData();
    return all[activeFnIdx] ? findSiblingFnInvUse(all[activeFnIdx], all) : {};
  }, [collectAllFunctionData, activeFnIdx]);
  // sub-category → sibling-function items NOT yet matched exactly — drives the orange 📦 stock icon
  // (as opposed to activeSiblingFnInvUse's orange RATE, shown only once an exact match is picked).
  // Heads-up only, same as activeSiblingFnInvUse — not gated by hideDiscountFromClient/Filler date.
  const activeSiblingFnSubcatOpportunity = useMemo(() => {
    const all = collectAllFunctionData();
    return all[activeFnIdx] ? findSiblingFnSubcatOpportunity(all[activeFnIdx], all, imsInventory) : {};
  }, [collectAllFunctionData, activeFnIdx, imsInventory]);

  // One full price run per function per set of inputs: the event total, its fixed-venue discount and Deal Check's rollups
  // each ask for the same function's grand several times a render. Keyed on the function object (allFunctionData hands
  // out the same one until something changes) and on the floral costing it used (read through a ref, so a change there
  // is checked here); the cache is new whenever any other input changes. Callers only read the result.
