        { const pSqft = printSqftOf(cfg, structRates.printMaterials); if (pSqft > 0) addSub(PRINT_TRUCK_SUB, (printRepeat || fvStruct) ? 0 : pSqft, pSqft, zk, "Print jobs", "", printClientWaived ? 0 : pSqft); }
