    const nameOf = new Map(pats.filter((p) => p?.id && String(p.name || "").trim()).map((p) => [p.id, String(p.name).trim()]));
    const stale = (el) => !!el && !!el.patternId && !el.invId && nameOf.has(el.patternId) && el.name !== nameOf.get(el.patternId);
