            + (ex.palette ? `, palette=${ex.palette}` : "") + (ex.time ? `, time=${ex.time}` : "")
            + (ex.lights ? `, lights total=${ex.lights}` : "")
            + (ex.elements && ex.elements.length ? `, elements: ${ex.elements.join(", ")}` : "") + ".";
