      const datePricing = { ...((s.datePricing && typeof s.datePricing === "object") ? s.datePricing : SETTINGS_DEFAULTS.datePricing), markedDates: assembleMarkedDatesFromRows(markedDateRows) };
      const situationalMultipliers = (s.situationalMultipliers && typeof s.situationalMultipliers === "object") ? s.situationalMultipliers : SIT_MULT_DEFAULTS;
      const situationalMultiplierCap = typeof s.situationalMultiplierCap === "number" ? s.situationalMultiplierCap : 1.8;
      const heavyElementRanges = assembleHeavyElementRangesFromRows(heavyElementRangeRows);
      const fabricBangaliRanges = assembleFabricBangaliRangesFromRows(fabricBangaliRangeRows);
      const trussLabourRanges = assembleTrussLabourRangesFromRows(trussLabourRangeRows);
      const fabricRftPerWorker = (typeof s.fabricRftPerWorker === "number" && s.fabricRftPerWorker > 0) ? s.fabricRftPerWorker : 100;
      const colourCatalogue = Array.isArray(s.colourCatalogue) ? s.colourCatalogue : [];
      const paletteCatalogue = Array.isArray(s.paletteCatalogue) ? s.paletteCatalogue : [];
      const paintableCategories = Array.isArray(s.paintableCategories) ? s.paintableCategories : [];
      const defaultPaintCostPerItem = typeof s.defaultPaintCostPerItem === "number" ? s.defaultPaintCostPerItem : 400;
      const carpetFreshMarkup = typeof s.carpetFreshMarkup === "number" ? s.carpetFreshMarkup : 40;
      // Agency fee — a flat % of the whole deal's client-facing total, billed to the guest on top
      // of decor/transport/power (Admin → Settings). Pure Ambria income: applied only where the
      // GUEST-facing total is computed (eventGrandTotal, the cost sheet, Deal Check's own "Deal
      // amount"/profit figure) — never inside internal cost, department income, or commission's own
      // revenue-share base, so it doesn't inflate what venues/salespeople are paid on.
      const agencyFeePct = typeof s.agencyFeePct === "number" ? s.agencyFeePct : DEFAULT_AGENCY_FEE_PCT;
      // Vendors (manpower avg-rate forecast) — match IMS rowToVendor shape (type/name from columns).
      const vendors = Array.isArray(vendorRows)
